import type { Question, SourceRef } from '../types';
import { systemsOpenQuestions } from './systems-open';

// Each row is authored independently; this helper only applies the common question schema.
const s3 = (pages: string, chapter: string): SourceRef => ({ title: 'TOPCIT ESSENCE ver.3 M3 시스템아키텍처 이해와 활용', chapter, pages: `인쇄 ${pages}쪽` });
const s4 = (pages: string, chapter: string): SourceRef => ({ title: 'TOPCIT ESSENCE ver.3 M4 정보보안 이해와 활용', chapter, pages: `인쇄 ${pages}쪽` });
const ref3 = (pages: string): SourceRef => ({ title: '2020 TOPCIT 문제풀이 03 시스템 아키텍쳐 및 해설', chapter: '제공 문제와 해설 재구성', pages: `PDF ${pages}쪽`, note: '파일명 기준 자료 식별. 공식 시행 회차를 단정하지 않음.' });
const ref4 = (pages: string): SourceRef => ({ title: '2020 TOPCIT 문제풀이 04 정보보안 이해와 활용', chapter: '제공 문제 재구성', pages: `PDF ${pages}쪽`, note: '오류가 있는 File 해설은 Oracle API로 교정함.' });
const fileAPI: SourceRef = { title: 'Oracle Java SE 8 File API', chapter: '추상 경로, exists(), delete()', url: 'https://docs.oracle.com/javase/8/docs/api/java/io/File.html' };
type Choices = [string, string, string, string];
const bank: Question[] = [];
function mc(round: number, n: number, source: SourceRef, topic: string, title: string, prompt: string, choices: Choices, reasons: Choices, keyPoints: string[]) {
  const shift = (round + n) % 4;
  const order = [0, 1, 2, 3].map(i => (i + shift) % 4);
  bank.push({ id: `sys-r${round}-${n}`, round, domain: 'systems', kind: 'choice', points: 5,
    difficulty: round < 3 ? '기초' : '응용', topic, title, prompt,
    options: order.map((original, i) => ({ id: String.fromCharCode(97 + i), text: choices[original], explanation: `${original === 0 ? '정답' : '오답'}. ${reasons[original]}` })),
    answer: String.fromCharCode(97 + order.indexOf(0)), explanation: reasons[0], keyPoints, sources: [source], origin: round === 1 ? 'reference-adapted' : 'original' });
}
// 1회차: 제공 자료의 사례와 핵심 개념을 재구성.
mc(1,1,ref3('1'),'컴퓨터 구조','RISC 제어장치','전통적인 RISC와 CISC의 설계 특성을 비교한다. RISC에 대한 설명 중 옳지 않은 것은?',
['복잡한 명령을 마이크로프로그램으로 해석하는 방식이 대표적인 특징이다.','단순하고 규칙적인 명령 형식을 지향한다.','명령 처리의 파이프라인 구성에 유리하게 설계한다.','메모리 접근과 레지스터 연산을 구분하는 설계가 대표적이다.'],
['마이크로프로그램으로 복잡한 명령을 구현하는 설명은 전통적인 CISC 비교 항목이다. 현대 구현 전체를 이분법으로 단정하지 않는다.','RISC는 비교적 단순한 명령 형식을 지향하므로 올바른 설명이다.','규칙적인 명령 형식은 파이프라인 설계에 유리하므로 올바르다.','Load/Store 계열 설계는 RISC의 대표 특성으로 제시된다.'],['명령 집합과 실제 구현을 구분','모든 명령이 한 클록이라는 단정 금지']);
mc(1,2,ref3('1'),'재해 복구','허용 데이터 손실','주문 서비스가 장애 시 최근 10분 동안의 데이터 손실까지 허용한다고 정했다. 이 목표를 나타내는 용어는?',
['RPO','RTO','MTTR','MTBF'],['RPO는 복구해야 할 데이터 시점의 목표이며 허용 가능한 데이터 손실 시간으로 표현한다.','RTO는 서비스 복구까지 허용하는 시간이다. 데이터 손실 시점과 구분한다.','MTTR은 실제 고장 수리·복구에 걸린 평균 시간 지표이다.','MTBF는 고장 사이의 평균 동작 시간으로 신뢰성 지표이다.'],['RPO=데이터 시점','RTO=복구 소요 시간']);
mc(1,3,ref3('2'),'TCP 소켓','서버 소켓 호출 순서','TCP 서버의 일반적인 흐름은 socket → bind → (가) → accept이다. 연결 요청을 받을 대기 상태로 만드는 (가)는?',
['listen','connect','recv','close'],['listen은 연결형 서버 소켓을 수신 대기 상태로 설정한다. 그 후 accept가 개별 연결을 받아들인다.','connect는 주로 클라이언트가 서버와 연결을 요청할 때 호출한다.','recv는 연결 후 데이터를 수신하는 호출이다.','close는 소켓 자원을 닫는 호출로 대기 상태를 만들지 않는다.'],['bind=주소 결합','listen=연결 대기','accept=연결 수락']);
mc(1,4,ref3('2'),'병렬 처리','반복 횟수와 스레드 수','OpenMP 병렬 반복문은 8번 실행되었다. 모든 출력에서 스레드 ID가 0 또는 1로 기록되었다. 출력에 확인된 참여 스레드 수는?',
['2개','8개','1개','출력 순서대로 0개와 1개가 번갈아 생성됨'],['서로 다른 ID의 집합이 {0,1}이므로 출력에서 확인되는 스레드는 2개다. 반복 횟수와 스레드 수는 다르다.','8은 반복 작업 수다. 한 스레드가 여러 반복을 수행할 수 있다.','0과 1이라는 서로 다른 스레드 ID가 확인되므로 1개가 아니다.','ID는 스레드 식별자이며 그 순간 생성된 스레드 개수가 아니다.'],['작업 수≠스레드 수','병렬 출력 순서는 고정되지 않음']);
mc(1,5,ref3('3'),'병렬 구조','명령 스트림 분류','하나의 제어장치가 동일한 명령을 여러 처리 요소에 보내고, 각 처리 요소가 서로 다른 영상 픽셀을 처리한다. Flynn 분류는?',
['SIMD','SISD','MISD','MIMD'],['하나의 명령 스트림과 여러 데이터 스트림을 병렬 처리하므로 SIMD다.','SISD는 명령과 데이터 스트림이 각각 하나다. 여러 픽셀 병렬 처리와 다르다.','MISD는 여러 명령 스트림이 하나의 데이터 스트림을 처리하는 분류다.','MIMD는 처리 요소들이 서로 다른 명령과 데이터 스트림을 실행할 수 있다.'],['SI=단일 명령','MD=복수 데이터']);
mc(1,6,ref4('1'),'IoT 보안','장치에서 새는 정보','의료 센서의 디버그 단자로 펌웨어가 추출되고 소비 전력의 차이로 비밀 연산 정보가 노출될 우려가 있다. 가장 직접적인 보안 대상은?',
["디바이스", "게이트웨이의 네트워크 접근통제", "클라우드 저장 데이터 보안", "전송 구간 암호화"],
["펌웨어 추출과 전력 부채널은 물리적 장치 및 장치 구현에서 발생하는 디바이스 보안 문제다.", "게이트웨이 보안은 장치와 외부망 사이 접근 경계를 다룬다. 사례는 장치 자체의 디버그·전력 정보를 이용한다.", "저장 서비스 보안은 클라우드 데이터와 권한을 다룬다. 물리 센서의 정보 누출과 대상이 다르다.", "전송 암호화는 네트워크 도청을 방어하지만 펌웨어 추출·전력 부채널을 직접 해결하지 못한다."],['디버그 인터페이스 보호','부채널은 구현에서 발생하는 정보 누출']);
mc(1,7,ref4('1'),'악성코드','문서 암호화와 금전 요구','업무 문서가 갑자기 암호화되고 복호화 대가로 금전을 요구하는 메시지가 나타났다. 가장 알맞은 분류는?',
["랜섬웨어", "파밍", "분산 서비스 거부(DDoS)", "크립토재킹"],
["랜섬웨어는 파일이나 시스템 사용을 막고 복구를 조건으로 금전을 요구하는 악성코드다.", "파밍은 접속 정보를 조작해 가짜 사이트로 유도하는 공격으로 파일 인질화와 구별된다.", "DDoS는 분산된 대량 요청 등으로 정상 서비스 이용을 방해한다. 파일 복호화 대가 요구와 다르다.", "크립토재킹은 사용자 자원을 무단 채굴에 이용한다. 금전 요구를 위한 파일 암호화와는 다르다."],['암호화 자체가 악성은 아님','행위의 목적과 피해로 구분']);
mc(1,8,ref4('2'),'무선 보안','기술적 위협과 관리 미흡','무선랜 위험 점검에서 기술적 공격 자체가 아니라 관리적 취약점으로 분류하기 가장 알맞은 것은?',
['AP 설치 현황과 담당자 관리 미흡','전파 도청','위조 AP로 접속 유도','대량 패킷에 의한 서비스 거부'],['자산 현황과 책임자 관리 부족은 관리적 통제의 결함이다. 공격 행위 자체와 구분한다.','도청은 전송된 정보를 수집하는 기술적 공격이다.','위조 AP는 이용자의 접속을 유도하는 기술적 위협이다.','대량 패킷으로 서비스 자원을 소진시키는 것은 기술적 가용성 공격이다.'],['관리적·기술적·물리적 통제','원인과 공격 행위를 구분']);
mc(1,9,ref4('2'),'네트워크 분리','인터넷망과 업무망','조직이 업무용 통신과 인터넷 접속을 물리적 장비 또는 논리적 환경으로 분리하여 직접 접근을 제한했다. 이를 무엇이라 하는가?',
["망분리", "VPN", "VLAN 간 무제한 라우팅", "망 내 모든 단말의 백신 설치"],
["망분리는 서로 다른 보안 영역의 네트워크를 물리적 또는 논리적으로 분리하는 통제다.", "VPN은 공용망 위에서 보호된 통신 경로를 제공하는 기술이다. 업무망·인터넷망 분리 그 자체와 다르다.", "VLAN으로 나누어도 모든 경로를 무제한 허용하면 사례의 접근 경계 통제가 구현되지 않는다.", "백신은 악성코드 방어 수단으로 업무망과 인터넷망의 연결 구조를 분리하지 않는다."],['논리적 분리도 가능','망 사이 자료 전달 경로도 통제']);
mc(1,10,ref4('3'),'시큐어 코딩','외부 파일 이름 결합','사용자가 보낸 filename을 서버 디렉터리 뒤에 그대로 연결하여 삭제한다. 우선 검토해야 할 위험은?',
["허용 범위를 벗어난 경로 접근", "SQL 삽입", "크로스 사이트 스크립팅", "정수 오버플로"],
["신뢰하지 않는 경로 입력으로 의도한 디렉터리 밖의 파일을 가리킬 수 있다. 서버가 관리하는 식별자 매핑 등으로 접근 대상을 제한해야 한다.", "SQL 삽입은 입력이 SQL 구조를 바꾸는 문제다. 제시한 코드의 직접 대상은 파일 경로다.", "XSS는 입력이 브라우저에서 실행 코드로 해석되는 문제다. 이 코드는 서버 파일 경로를 다룬다.", "정수 오버플로는 수치 표현 범위를 넘는 연산 문제로 제시한 문자열 경로 결합의 핵심 위험과 다르다."],['입력 검증과 권한 검증','경로 문자열 직접 결합 회피']);
mc(1,11,s3('46','III 운영체제'),'프로세스','입출력을 기다리는 작업','실행 중이던 프로세스가 디스크 읽기를 요청하여 결과를 기다린다. 일반적인 상태 전이는?',
['실행 → 대기','준비 → 종료','대기 → 실행으로 즉시 강제 이동','종료 → 준비'],['입출력이 끝날 때까지 CPU를 사용할 수 없으므로 실행 상태에서 대기 상태로 바뀐다.','준비는 CPU 배정을 기다리는 상태이며 입출력 요청만으로 종료되지 않는다.','입출력이 완료되면 보통 준비 상태로 돌아가 스케줄링을 기다린다.','종료된 프로세스는 같은 실행 흐름의 준비 상태로 되돌아가지 않는다.'],['준비=CPU 대기','대기=사건·입출력 완료 대기']);
mc(1,12,s3('185','XIV 전송 계층'),'UDP','UDP의 제공 기능','UDP를 사용하는 실시간 센서 전송을 설계한다. UDP 자체가 제공한다고 볼 수 없는 기능은?',
['손실 데이터의 자동 재전송과 순서 보장','데이터그램 단위 전송','연결 설정 없는 전송','포트 번호를 통한 응용 식별'],['UDP 자체는 손실 재전송이나 순서 보장을 제공하지 않는다. 필요하면 응용 계층이 별도로 구현한다.','UDP는 메시지 경계를 가진 데이터그램을 전송한다.','UDP는 TCP처럼 사전 연결 수립 절차가 필수인 프로토콜이 아니다.','UDP 헤더의 출발지·목적지 포트가 응용을 구분한다.'],['전송 신뢰성은 자동 제공되지 않음','응용에서 보완 가능']);
mc(1,13,s4('13','I 정보보안 개요'),'보안 목표','허가받지 않은 성적 수정','학생이 권한 없이 성적 값을 변경했지만 서비스는 계속 동작하고 있다. 직접적으로 훼손된 보안 속성은?',
['무결성','가용성','기밀성만','압축률'],['무결성은 정보가 허가 없이 변경되거나 훼손되지 않게 하는 속성이다. 값의 무단 수정이 핵심이다.','가용성은 필요할 때 서비스를 이용할 수 있는 속성이다. 사례의 핵심은 중단이 아니다.','기밀성은 비인가 열람·노출 방지다. 무단 변경을 기밀성만으로 설명할 수 없다.','압축률은 저장 효율 지표로 CIA 보안 속성이 아니다.'],['기밀성=노출 방지','무결성=변경 통제','가용성=이용 보장']);
mc(1,14,s4('35','II 정보보안 기법'),'사용자 인증','인증 요소의 조합','서로 다른 인증 요소를 결합한 예로 가장 적절한 것은?',
['비밀번호와 소지한 보안 토큰','비밀번호와 별도 PIN','비밀번호와 비밀 질문 답','서로 다른 비밀번호 두 개'],['비밀번호는 지식 요소, 보안 토큰은 소지 요소다. 서로 다른 범주의 요소를 결합했다.','비밀번호와 PIN은 모두 알고 있는 정보를 이용하는 지식 요소다.','비밀 질문 답도 지식 요소이므로 요소 범주가 같아진다.','두 개의 비밀번호를 요구해도 둘 다 지식 요소다.'],['단계 수와 요소 수는 다름','지식·소지·생체']);
mc(1,15,s4('41','II 접근통제'),'접근통제','직무에 맞춘 권한','회계 담당자에게 결산 역할을 할당하고 그 역할에 연결된 권한을 부여한다. 대표적인 접근통제 모델은?',
['RBAC','DAC','MAC','RAID'],['RBAC는 사용자의 직무 역할에 권한을 연결한다. 역할 변경으로 권한을 일관되게 관리할 수 있다.','DAC는 객체 소유자가 주체별 접근권한을 재량으로 부여하는 모델이다.','MAC는 보안 등급·허가 수준 등 강제 정책으로 접근을 통제한다.','RAID는 디스크 배열 기술이며 사용자 권한 모델이 아니다.'],['역할에 권한 부여','역할 변경 시 권한 회수']);

// 2회차: OS 실행과 기본 보안 통제.
mc(2,1,s3('46','III 운영체제'),'프로세스 제어','중단한 실행을 이어 가기','운영체제가 다른 프로세스로 전환한 뒤 기존 프로세스의 다음 명령부터 실행하려 한다. 보존해야 할 정보로 가장 적절한 것은?',
["프로그램 카운터와 레지스터를 포함한 실행 문맥", "프로세스 실행파일의 경로만", "프로세스에 배정된 메모리 크기만", "프로세스의 우선순위만"],
["PCB 등에서 실행 문맥을 관리해야 중단 지점부터 재개할 수 있다. PC는 다음 실행 위치를 나타낸다.", "실행파일 경로만으로는 실행 중 변경된 레지스터 값과 다음 명령 위치를 복원할 수 없다.", "메모리 크기는 자원 정보지만 중단된 CPU 문맥 자체를 표현하지 않는다.", "우선순위는 다음 CPU 배정 판단에 쓰지만 중단 지점과 레지스터 상태를 대신하지 않는다."],['문맥 교환','PCB와 CPU 상태']);
mc(2,2,s3('49','III 운영체제'),'동기화','재고가 하나 사라지는 이유','두 스레드가 재고 10을 동시에 읽고 각각 1을 감소시킨 뒤 9를 저장했다. 기대값 8이 나오지 않은 핵심 원인은?',
['공유 값 갱신에 대한 경쟁 상태','디스크 조각 모음','모든 스레드의 교착 상태','정상적인 원자 연산'],['읽기·계산·쓰기가 다른 실행과 섞여 한 갱신이 유실된 경쟁 상태다. 임계구역 보호가 필요하다.','조각 모음은 저장공간 배치를 개선하며 공유 변수 갱신 유실과는 다르다.','교착은 서로 자원을 기다려 진행 못하는 상태다. 여기서는 실행됐지만 결과가 틀렸다.','여러 단계 갱신이 원자적으로 실행되지 않았으므로 이 설명은 맞지 않는다.'],['임계구역 보호','read-modify-write는 자동 원자적이지 않음']);
mc(2,3,s3('50','III 운영체제'),'교착 예방','잠금 획득 순서 통일','모든 스레드가 파일 잠금보다 DB 잠금을 먼저 획득하도록 규칙을 통일했다. 주로 제거하려는 교착 필요조건은?',
['순환 대기','상호 배제','비선점','점유 대기 자체'],['전역적으로 자원 획득 순서를 정하면 자원 대기 그래프의 순환을 막을 수 있다.','한 자원을 한 스레드가 독점하는 상호 배제는 이 규칙으로 사라지지 않는다.','다른 스레드의 잠금을 강제 회수하는 정책이 아니므로 비선점 제거가 아니다.','먼저 얻은 잠금을 보유하며 다음 것을 기다릴 수 있어 점유 대기는 남는다.'],['교착의 네 조건','자원 획득 순서']);
mc(2,4,s3('54','III 운영체제'),'스케줄링','대화형 응답의 시간 할당','각 준비 프로세스에 같은 시간 조각을 주고, 시간이 끝나면 큐 뒤로 보내는 정책은?',
['라운드 로빈','비선점 SJF','FCFS','OPT'],['라운드 로빈은 정해진 시간 할당량을 순환 배정하는 선점형 정책이다.','비선점 SJF는 실행 시간이 가장 짧은 작업을 고르고 실행 중 선점하지 않는다.','FCFS는 도착 순으로 실행하며 정해진 시간마다 강제로 교체하지 않는다.','OPT는 미래 참조를 이용하는 페이지 교체 기준이지 CPU 스케줄러가 아니다.'],['RR은 선점형','시간 조각과 문맥 교환 비용']);
mc(2,5,s3('55','III 운영체제'),'가상 메모리','페이지 교체 기준','메모리 부족 시 가장 오랫동안 참조되지 않은 페이지를 내보냈다. 사용한 알고리즘은?',
['LRU','FIFO','LFU','라운드 로빈'],['LRU는 최근 사용 시점을 비교하여 가장 오래 사용되지 않은 페이지를 교체한다.','FIFO는 메모리에 가장 먼저 적재된 페이지를 내보낸다. 참조 시점과 다르다.','LFU는 참조 횟수가 가장 적은 페이지를 선택한다. 최근성과 빈도를 구분한다.','라운드 로빈은 CPU 시간 배정 정책이다. 페이지 최근 참조 순서와 무관하다.'],['최근성=LRU','빈도=LFU','적재 순서=FIFO']);
mc(2,6,s3('53','III 운영체제'),'메모리 관리','인접한 빈 공간','연속 메모리 할당에서 해제된 인접 빈 블록들을 하나의 큰 빈 블록으로 합쳤다. 이 작업은?',
["병합(coalescing)", "압축(compaction)", "페이징(paging)", "스와핑(swapping)"],
["병합은 서로 인접한 빈 공간을 하나로 합쳐 더 큰 연속 할당 요청에 대응하는 작업이다.", "압축은 사용 중인 메모리 블록을 이동하여 빈 공간을 모으는 방식이다. 사례는 인접한 빈 블록만 합친다.", "페이징은 고정 크기 페이지와 프레임으로 메모리를 관리하는 방식이다. 빈 블록 결합 작업과 다르다.", "스와핑은 프로세스 등의 메모리 내용을 보조기억장치로 내보내거나 다시 가져오는 작업이다."],['인접 빈 공간의 결합','외부 단편화']);
mc(2,7,s3('69','IV 컴퓨터 구조'),'지역성','방금 계산한 값 재사용','반복문에서 동일한 누적 변수를 계속 읽고 쓴다. 캐시 효과와 가장 직접적으로 연결되는 지역성은?',
["시간적 지역성", "공간적 지역성", "순차적 지역성", "캐시 일관성"],
["최근 사용한 데이터를 가까운 미래에 다시 쓰는 시간적 지역성의 예다.", "공간적 지역성은 참조 주소 주변 주소도 곧 참조될 가능성이다. 여기서는 같은 누적 변수의 재사용이 핵심이다.", "순차적 지역성은 명령·데이터가 순서대로 접근되는 경향이다. 동일한 변수 반복 참조는 시간적 지역성이다.", "캐시 일관성은 여러 캐시 사본이 데이터 변경을 일관되게 반영하는 문제로 재참조 경향과 다르다."],['같은 주소 재사용','캐시는 지역성 활용']);
mc(2,8,s3('70','IV 컴퓨터 구조'),'입출력','CPU를 거치지 않는 블록 전달','네트워크 장치가 큰 데이터를 주기억장치로 옮길 때 CPU가 바이트마다 복사하지 않도록 한다. 적합한 방식은?',
["DMA", "프로그램 제어 입출력", "매 바이트 인터럽트 후 CPU 복사", "메모리 매핑 입출력 주소만 설정"],
["DMA는 장치와 메모리 사이 전송을 전용 제어로 수행하여 CPU의 세부 복사 부담을 줄인다.", "프로그램 제어 입출력은 CPU가 상태를 확인하고 데이터를 옮기는 부담이 크다.", "인터럽트를 사용해도 매 바이트 CPU가 복사하면 블록 전송을 DMA에 맡기는 것과 다르다.", "메모리 매핑은 장치 레지스터 접근 주소 방식을 정한다. 그것만으로 DMA 전송이 구현되지는 않는다."],['DMA에도 초기 설정은 필요','전송 완료 통지']);
mc(2,9,s4('40','II 접근통제'),'인증과 인가','로그인은 되지만 조회는 거절','직원은 비밀번호 검증을 통과했지만 다른 부서의 급여 조회는 거절됐다. 두 번째 판단은?',
["인가", "식별", "신원 인증", "세션 수립"],
["인가는 인증된 주체가 특정 자원·행위를 수행할 권한이 있는지 판단한다.", "식별은 ID로 자신이 누구인지 제시하는 단계다. 자원별 허용 행위 판단과 다르다.", "인증은 신원 확인으로 비밀번호 검증이 이 단계다. 신원 확인 성공은 모든 데이터 접근 허용을 뜻하지 않는다.", "세션 수립은 요청 간 상태 유지를 위한 활동으로 급여 조회의 권한 판정과는 다르다."],['인증≠인가','요청마다 권한 확인']);
mc(2,10,s4('41','II 접근통제'),'최소 권한','조회 서비스 계정','리포트 서비스가 매출을 조회만 한다. 가장 적절한 DB 권한 구성은?',
['필요한 조회 범위만 허용','관리자 권한을 항상 부여','삭제 권한까지 기본 부여','공유 관리자 비밀번호 사용'],['기능 수행에 필요한 최소 조회 권한을 부여하면 계정 침해 시 피해 범위를 줄인다.','관리자 권한은 서비스가 필요로 하지 않는 광범위 권한까지 제공한다.','조회 기능에 삭제 권한은 불필요하므로 최소 권한 원칙을 위반한다.','공유 관리자 계정은 권한 과다와 행위 추적의 어려움을 함께 만든다.'],['최소 권한','서비스별 계정 분리']);
mc(2,11,s4('96','VII 시스템 보안'),'계정 관리','퇴사자 계정 처리','퇴사자의 개인 계정이 업무 서버에 남아 있다. 우선 적용할 통제로 적절한 것은?',
["접근 필요 여부를 확인하고 해당 계정 접근 권한 회수", "비밀번호를 변경하되 기존 접근권한은 유지", "다른 직원에게 같은 계정을 승계", "계정 표시 이름만 퇴사로 변경"],
["더 이상 업무 권한이 없는 계정의 접근을 회수하고 필요한 기록은 별도 보존해야 한다.", "비밀번호를 바꾸는 것만으로 접근 필요가 없는 계정 자체의 잔여 권한 문제가 해소되지는 않는다.", "개인 계정을 넘겨주면 사용자별 행위 추적과 권한 생명주기 관리가 어려워진다.", "이름 변경은 실제 인증·인가 정책을 차단하지 않으므로 퇴사자 접근 회수를 대신하지 않는다."],['계정 생명주기 관리','기록 보존과 접근 허용을 구분']);
mc(2,12,s4('97','VII 시스템 보안'),'세션 통제','자리를 비운 운영자','공용 관리 단말에서 운영자가 로그아웃을 잊었다. 일정 시간 사용하지 않으면 세션을 종료하도록 하는 통제는?',
["유휴 세션 타임아웃", "비밀번호 복잡성 검사만", "로그인 시 CAPTCHA만", "접속 IP 허용 목록만"],
["유휴 타임아웃은 방치된 인증 세션을 통한 비인가 접근 위험을 줄인다.", "복잡성 검사는 비밀번호 추측을 어렵게 하지만 이미 인증된 방치 세션을 종료하지 않는다.", "CAPTCHA는 자동화된 로그인 시도 제한에 쓰이지만 인증 후 방치 세션과 다르다.", "IP 허용 목록은 접속 출처를 제한하며 허용된 공용 단말의 방치 세션을 직접 만료시키지 않는다."],['유휴 시간 제한','인증 후 세션도 보호']);
mc(2,13,s4('27','II 암호 기술'),'해시','배포 파일의 변경 확인','신뢰할 수 있는 경로에서 받은 기대 해시와 다운로드 파일의 해시가 다르다. 합리적인 판단은?',
['파일이 기대한 바이트열과 다르므로 사용을 중단하고 확인한다.','해시가 다르면 파일 기밀성이 보장된다.','해시는 암호문이므로 비밀키로 복호화한다.','서로 다른 해시는 항상 정상적인 압축 때문이다.'],['같은 해시 알고리즘으로 계산한 결과가 다르면 입력이 다르다. 전송 오류나 변조 가능성을 확인해야 한다.','해시는 변경 검출에 쓰며 내용 비밀 보호를 제공하지 않는다.','일반적인 암호학적 해시는 원문 복원을 위한 복호화 함수가 아니다.','압축 등의 합의된 변환 조건이 없으므로 불일치를 임의로 정상이라 판단할 수 없다.'],['기대 해시의 신뢰성','해시는 암호화와 다름']);
mc(2,14,s4('24','II 암호 기술'),'대칭키','대량 데이터 암호화','송신자와 수신자가 같은 비밀키를 공유하여 대량 데이터를 빠르게 암·복호화한다. 해당 방식은?',
['대칭키 암호','공개키 암호만','일방향 해시','데이터 인코딩'],['대칭키 암호는 같은 비밀키를 공유하며 대량 데이터 처리에 널리 사용된다. 키 전달과 보호가 중요하다.','공개키 암호는 공개키와 개인키 쌍을 사용하므로 같은 비밀키 공유라는 설명과 다르다.','해시는 원문 복원을 위한 암·복호화 쌍을 제공하지 않는다.','인코딩은 표현 변환으로 키를 이용한 비밀 보호와 다르다.'],['빠른 대량 처리','비밀키 배포 문제']);
mc(2,15,s4('58','IV 보안관리체계'),'ISMS','한 번 점검하면 끝일까','서비스 출시 후에도 위험을 재평가하고 통제를 운영·점검·개선하는 정보보호 활동 체계는?',
["정보보호 관리체계", "일회성 침투 시험", "제품의 암호화 기능 인증만", "단일 방화벽 규칙 설치"],
["정보보호 관리체계는 위험 기반의 통제 수립부터 운영·점검·개선까지 지속적으로 관리한다.", "침투 시험은 취약점 검증 활동의 하나이며 지속적 조직 관리체계 전체와는 다르다.", "암호화 제품 검증은 특정 기능에 대한 평가로 조직의 위험·운영·개선 체계 전체가 아니다.", "방화벽 규칙은 기술적 통제 한 가지로 정책·책임·점검·개선 전체를 대신하지 않는다."],['지속적 개선','위험 기반 통제']);

// 3회차: LAN, 주소, 경계와 공격 해석.
mc(3,1,s3('146–147','XI 데이터링크 계층'),'ARP','같은 LAN의 주소 찾기','호스트가 같은 IPv4 서브넷의 상대 IP는 알지만 MAC 주소를 모른다. 먼저 사용할 프로토콜은?',
['ARP','DNS','SMTP','BGP'],['ARP는 로컬 링크에서 IPv4 주소에 대응하는 MAC 주소를 알아낸다.','DNS는 도메인 이름 등의 레코드를 조회하며 이웃 MAC 주소를 구하지 않는다.','SMTP는 전자우편 전송 프로토콜이다.','BGP는 자율 시스템 간 경로 교환 프로토콜이다.'],['IP→MAC','ARP 요청은 링크 범위']);
mc(3,2,s3('158','XII 네트워크 계층'),'스위칭','스위치 학습 기준','L2 스위치가 프레임을 받아 MAC 주소 테이블을 갱신한다. 일반적으로 어떤 정보를 학습하는가?',
['출발지 MAC과 수신 포트','목적지 TCP 포트와 웹 URL','패킷 내용의 개인정보','DNS TTL만'],['수신 프레임의 출발지 MAC이 어느 포트 뒤에 있는지 학습하여 이후 전달에 사용한다.','L2 MAC 학습은 TCP 포트나 URL을 기준으로 하지 않는다.','개인정보 내용 분석은 기본 MAC 학습 역할이 아니다.','DNS TTL은 이름 해석 캐시 수명으로 MAC 주소 테이블 학습과 다르다.'],['출발지로 학습','목적지로 전달 결정']);
mc(3,3,s3('158','XII 네트워크 계층'),'루프 방지','이중 연결된 스위치','가용성을 위해 스위치를 이중 연결했더니 L2 루프가 우려된다. 일부 링크를 논리적으로 차단하는 대표 기술은?',
["STP", "VLAN", "링크 집성만 구성하고 루프 검토 생략", "라우팅 프로토콜 RIP"],
["STP는 스패닝 트리를 구성하여 중복 링크의 루프를 억제한다. 물리적 이중화를 모두 제거할 필요는 없다.", "VLAN은 브로드캐스트 영역을 논리적으로 나누며 동일 VLAN 안의 중복 브리지 루프를 자동 해결하는 설명이 아니다.", "링크 집성은 여러 링크를 논리적으로 묶지만 전체 브리지 토폴로지의 루프 검토를 대신하지 않는다.", "RIP는 IP 경로 교환 프로토콜이다. 사례의 이더넷 브리지 루프에 쓰는 STP와 다르다."],['L2 루프','물리 중복과 논리 경로']);
mc(3,4,s3('158','XII 네트워크 계층'),'VLAN','부서별 브로드캐스트 분리','같은 물리 스위치에서 연구실과 방문자망의 브로드캐스트 도메인을 분리하고 싶다. 적절한 기능은?',
["VLAN", "포트 미러링", "MAC 주소 학습만", "STP만 적용"],
["VLAN은 물리 구성과 별개로 논리적인 L2 브로드캐스트 영역을 나눈다. 영역 간 접근 정책은 추가 통제한다.", "포트 미러링은 분석을 위한 트래픽 사본 전달 기능이다. 부서별 브로드캐스트 영역을 나누지 않는다.", "MAC 학습은 목적지 전달 포트를 고르는 데 쓰며 같은 VLAN의 브로드캐스트를 부서별 분리하지 않는다.", "STP는 L2 루프를 막는 프로토콜이며 부서별 논리 영역 분리를 위한 VLAN과 다르다."],['논리적 L2 분리','VLAN 간 라우팅 정책']);
mc(3,5,s3('169–170','XIII IP 주소'),'서브넷','/26 호스트 수','일반 IPv4 서브넷 /26에서 네트워크 주소와 브로드캐스트 주소를 제외한 사용 가능한 호스트 주소 수는?',
['62','64','30','254'],['호스트 비트는 32−26=6이므로 전체 64개에서 예약 주소 2개를 제외하면 62개다.','64는 전체 주소 개수로 두 예약 주소를 포함했다.','30은 /27의 일반적인 사용 가능 호스트 수다.','254는 /24의 일반적인 사용 가능 호스트 수다.'],['2의 호스트비트 제곱','일반 서브넷 예약 주소 두 개']);
mc(3,6,s3('172','XIII IP 주소'),'NAT','공인 주소 한 개 공유','여러 내부 PC가 하나의 공인 IPv4 주소로 동시에 인터넷에 접속한다. 연결 구분에 주소와 함께 변환하는 것은?',
["전송 계층 포트 번호", "MAC 주소", "DNS 질의 ID만", "IP TTL"],
["NAPT는 IP 주소와 포트 번호의 대응을 관리해 여러 내부 연결을 하나의 공인 주소로 구분한다.", "MAC 주소는 링크 단위 전달 주소다. NAPT의 인터넷 연결 매핑은 IP와 전송 계층 포트를 사용한다.", "DNS 질의 ID는 DNS 요청·응답을 맞추는 값으로 여러 종류의 인터넷 연결을 매핑하는 기준이 아니다.", "TTL은 홉 수 제한 필드이며 동시 내부 연결의 응답 대상을 구분하기 위한 식별자가 아니다."],['NAT와 NAPT','주소·포트 매핑']);
mc(3,7,s3('160','XII 네트워크 계층'),'IP','반복 전달 방지','잘못된 경로 때문에 패킷이 라우터 사이에서 계속 돌 수 있다. IPv4에서 전달 횟수를 제한하는 필드는?',
['TTL','TCP 수신 윈도','UDP 길이','MAC 학습 시간만'],['라우터가 TTL을 감소시키며 소진된 패킷을 폐기하므로 무한 전달을 제한한다.','TCP 수신 윈도는 수신자의 수용 능력을 알리는 흐름 제어 정보다.','UDP 길이는 데이터그램 크기 정보이며 홉 수를 제한하지 않는다.','MAC 학습 시간은 스위치 주소 테이블 유지와 관련되며 IP 패킷의 홉 제한이 아니다.'],['홉마다 감소','TTL 소진 시 폐기']);
mc(3,8,s3('166','XII 라우팅'),'라우팅','인터넷 사업자 간 경로','서로 다른 자율 시스템 사이에 정책을 반영하여 경로를 교환하려 한다. 대표적인 프로토콜은?',
['BGP','OSPF','ARP','RIP만 사용해야 함'],['BGP는 AS 경로 정보를 이용하는 대표적인 자율 시스템 간 라우팅 프로토콜이다.','OSPF는 주로 하나의 AS 내부에서 링크 상태 정보를 사용하는 IGP다.','ARP는 로컬 링크의 주소 대응을 구한다. AS 사이 경로 교환과 다르다.','RIP는 거리 벡터 기반 내부 라우팅으로 인터넷 AS 간 정책 라우팅의 대표가 아니다.'],['IGP와 EGP','AS 경로와 정책']);
mc(3,9,s4('101','VIII 네트워크 보안'),'수동 공격','패킷을 바꾸지 않는 공격','공격자가 통신 내용을 몰래 읽기만 하고 패킷을 변경하거나 차단하지 않는다. 분류로 적절한 것은?',
['수동적 공격','서비스 거부','데이터 변조','정상적인 권한 위임'],['도청은 정보를 수집하지만 자원 상태를 직접 바꾸지 않는 수동적 공격이다. 암호화 등 예방이 중요하다.','서비스 거부는 정상 이용을 방해하는 적극적 가용성 공격이다.','변조는 정보 내용을 바꾸는 적극적 공격이다.','무단 도청은 허가된 권한 위임이 아니다.'],['수동=관찰·수집','능동=변경·방해']);
mc(3,10,s4('107','VIII 네트워크 보안'),'보안 프로토콜','원격 셸 보호','운영자가 원격 서버의 명령줄을 이용해야 한다. 암호화된 원격 접속에 적합한 프로토콜은?',
["SSH", "Telnet", "HTTPS 웹 페이지 제공", "IPsec 터널만 있고 셸 서비스는 없음"],
["SSH는 원격 접속에서 인증과 통신 보호를 제공하는 대표적인 프로토콜이다.", "Telnet의 기본 평문 전송은 명령과 자격증명 노출 위험이 있어 보호된 원격 셸 요구에 맞지 않는다.", "HTTPS는 웹 통신을 보호하지만 자체적으로 운영체제 원격 셸을 제공하는 프로토콜은 아니다.", "IPsec은 IP 통신 경로를 보호할 수 있지만 명령줄 로그인과 셸 서비스를 자체 제공하는 것은 아니다."],['원격 관리 채널 암호화','서버 신원 확인도 필요']);
mc(3,11,s4('110','VIII 보안 프로토콜'),'IPsec','지점 간 보안 통신','응용 프로그램을 각각 고치지 않고 두 지점 게이트웨이 사이 IP 패킷을 보호하려 한다. 가장 직접적인 기술은?',
["IPsec VPN", "TLS를 각 웹 응용에 개별 적용", "호스트별 로컬 파일 암호화", "VLAN 이름만 동일하게 설정"],
["IPsec은 IP 계층 트래픽을 보호하므로 게이트웨이 사이 VPN 구현에 사용할 수 있다.", "TLS는 응용 통신 보호에 활용되지만 이 사례는 응용 변경 없이 게이트웨이 사이 IP 트래픽 전체를 보호하려 한다.", "저장 파일 암호화는 지점 사이 전송 중인 패킷을 직접 보호하지 않는다.", "VLAN 이름이 같아도 공용망 구간의 인증·암호화 터널이 자동으로 구성되지 않는다."],['네트워크 계층 보호','게이트웨이 간 터널']);
mc(3,12,s4('116–117','VIII 무선랜 보안'),'무선 AP','직원이 설치한 공유기','직원이 승인 없이 사내 유선망에 개인 공유기를 연결했다. 외부에서 내부망으로 들어오는 우회 경로가 생겼다. 핵심 대응은?',
["AP 자산 식별과 비인가 AP 접속 통제", "SSID 숨김만 적용", "MAC 주소 필터만으로 승인 여부 판단", "무선 암호만 교체하고 자산 관리는 생략"],
["비인가 AP를 찾아 승인 절차와 접속 통제를 적용해야 한다. 이름만으로 신뢰할 수 없다.", "SSID 숨김은 장치가 승인된 AP인지 관리하고 비인가 연결을 차단하는 절차를 대체하지 못한다.", "MAC 주소는 위조될 수 있으며 승인된 자산·접속 경로 점검 없이 이것만으로 신뢰할 수 없다.", "암호 교체는 통제 한 가지지만 승인 없는 AP가 내부망 우회 경로를 만드는 문제는 별도 관리해야 한다."],['Rogue AP','자산 관리와 기술적 탐지 결합']);
mc(3,13,s4('47','III 보안 위협'),'파밍','주소는 맞는데 서버가 다르다','사용자가 정상 은행 도메인을 입력했지만 변조된 주소 해석 정보 때문에 가짜 사이트로 접속했다. 가장 적절한 명칭은?',
["파밍", "피싱 메시지로 링크 클릭 유도", "스니핑", "랜섬웨어"],
["파밍은 주소 해석이나 관련 접속 정보를 조작하여 가짜 사이트로 유도하는 방식이다.", "피싱도 가짜 사이트를 활용할 수 있지만 사례의 구분 단서는 정상 주소 입력 뒤 주소 해석이 조작됐다는 점이다.", "스니핑은 통신을 수집하는 행위다. 주소 해석을 바꿔 가짜 사이트로 유도하는 행위와 다르다.", "랜섬웨어는 파일·시스템 이용을 막고 복구 대가를 요구하는 악성코드다."],['도메인 입력만으로 안전 보장 안 됨','접속 대상 신원 확인']);
mc(3,14,s4('64','IV 보안 표준'),'취약점 식별','제품의 특정 취약점 공유','운영팀과 공급업체가 동일한 공개 취약점 한 건을 지칭하기 위해 공통 식별자를 사용하려 한다. 가장 알맞은 것은?',
['CVE ID','CWE 분류만','CVSS 점수만','RPO 값'],['CVE ID는 공개된 특정 취약점 기록을 식별하는 데 사용한다.','CWE는 취약점이 발생하는 약점 유형의 분류로 특정 사건 식별자와 다르다.','CVSS는 취약점 심각도 평가 체계이며 같은 점수의 취약점이 여럿일 수 있다.','RPO는 복구 데이터 시점 목표로 취약점 식별 체계가 아니다.'],['CVE=개별 취약점','CWE=약점 유형','CVSS=심각도']);
mc(3,15,s4('101','VIII 네트워크 보안'),'DMZ','공개 웹과 내부 DB','외부 사용자에게 공개하는 웹 서버와 내부 급여 DB의 네트워크 배치를 설계한다. 적절한 선택은?',
["웹 서버는 DMZ에 두고 내부 DB로의 접근은 필요한 흐름만 허용", "웹과 DB를 같은 공개 영역에 두고 서버 이름으로만 구분", "웹 침해에 대비해 인터넷에서 DB 직접 접속도 허용", "DMZ와 내부 사이 모든 포트를 허용"],
["DMZ는 외부 공개 서비스와 내부 중요 자원 사이의 경계다. 실제 접근 정책으로 필요한 통신만 허용해야 한다.", "명칭만 구분해도 실제 접근 경계가 같으면 공개 서버 침해가 내부 데이터에 영향을 줄 수 있다.", "인터넷에서 민감 DB로 직접 들어오는 경로를 추가하면 필요한 접근 범위를 넘어 노출이 증가한다.", "DMZ 구성 자체보다 실제 허용 규칙이 중요하다. 모든 포트 허용은 필요한 통신만 허용하는 원칙에 어긋난다."],['공개 영역과 내부 영역 분리','기본 거부·필요 통신 허용']);

// 4회차: 하드웨어 성능과 암호의 역할.
mc(4,1,s3('66','IV 컴퓨터 구조'),'명령 실행','다음 명령 주소','CPU가 명령을 순차 실행할 때 다음에 가져올 명령 위치를 나타내는 대표 레지스터는?',
["프로그램 카운터", "명령 레지스터(IR)", "메모리 주소 레지스터(MAR)", "누산기(Accumulator)"],
["프로그램 카운터는 다음 실행·인출할 명령 주소를 관리한다.", "IR은 현재 처리 중인 명령을 보관한다. 다음 명령의 위치를 관리하는 PC와 다르다.", "MAR은 메모리에 접근할 주소를 보관한다. 명령 실행 순서의 다음 위치 관리 역할과 구분한다.", "누산기는 산술·논리 연산 결과를 보관하는 용도로 다음 명령 주소 역할이 아니다."],['PC=명령 위치','레지스터별 역할']);
mc(4,2,s3('69','IV 컴퓨터 구조'),'지역성','배열을 순서대로 읽기','연속 주소에 저장된 배열을 처음부터 끝까지 읽을 때 캐시 블록의 주변 데이터도 곧 사용된다. 이 특징은?',
["공간적 지역성", "시간적 지역성", "캐시 일관성", "페이지 교체 빈도"],
["공간적 지역성은 참조한 주소 주변 데이터를 참조할 가능성이 높다는 성질이다.", "시간적 지역성은 같은 데이터가 곧 재사용되는 경향이다. 주변 주소의 연속 사용은 공간적 지역성이다.", "캐시 일관성은 다중 캐시 사본의 값 관계를 다루며 인접 데이터 접근 경향을 뜻하지 않는다.", "교체 빈도는 메모리 압박 결과 지표이며 배열의 주소 인접성 자체를 설명하는 용어가 아니다."],['인접 주소 접근','캐시 라인의 활용']);
mc(4,3,s3('81','V 병렬 처리'),'파이프라인','앞 명령의 결과 대기','덧셈 명령의 결과를 바로 다음 곱셈 명령이 사용해야 하는데 아직 결과가 준비되지 않았다. 해당 해저드는?',
['데이터 해저드','제어 해저드','구조적 해저드만','네트워크 혼잡'],['명령 간 데이터 의존성 때문에 결과를 기다리는 데이터 해저드다.','제어 해저드는 분기 등으로 다음 명령 흐름이 확정되지 않는 문제다.','구조적 해저드는 필요한 하드웨어 자원을 동시에 사용하려는 충돌이다. 주어진 원인은 결과 의존성이다.','네트워크 혼잡은 전송 자원 과부하로 CPU 명령 의존성과 다르다.'],['데이터 의존성','포워딩·정지 등 대응']);
mc(4,4,s3('78','V 병렬 처리'),'병렬 시스템','메모리를 공유하는 CPU들','여러 프로세서가 하나의 주기억장치 주소 공간을 공유한다. 프로세서 수가 늘면서 공유 버스 경합이 커졌다. 대표 구조는?',
["SMP", "MPP", "단일 프로세서 시간 분할", "SIMD라는 명칭만으로 특정"],
["SMP는 다수 프로세서가 메모리 등 자원을 공유하며 공유 경로 경합이 확장성 제약이 될 수 있다.", "MPP는 일반적으로 노드별 독립 메모리와 메시지 통신을 사용하는 구조로 공유 메모리 SMP와 대비된다.", "시간 분할은 하나의 CPU가 여러 프로세스를 번갈아 실행하는 방식으로 다수 물리 CPU 공유 구조와 다르다.", "SIMD는 명령·데이터 스트림 기준 분류이므로 공유 버스 기반 다중 CPU라는 핵심 구조 명칭을 대체하지 못한다."],['공유 메모리','경합과 확장성']);
mc(4,5,s3('81','V 병렬 처리'),'병렬 프로그래밍','독립 메모리 노드 간 전달','각 서버가 독립 메모리를 가진 계산 클러스터에서 계산 결과를 명시적으로 주고받으려 한다. 대표적인 통신 방식은?',
["MPI 메시지 전달", "공유 메모리 전용 OpenMP만 사용", "한 노드의 포인터를 다른 노드에서 그대로 사용", "모든 노드의 변수 이름을 동일하게 지정"],
["MPI는 분산된 처리 요소 간 메시지 전달을 위한 인터페이스로 독립 메모리 환경에 적합하다.", "OpenMP는 대표적으로 공유 메모리 병렬 실행을 다룬다. 독립 노드 사이 메시지 교환에는 MPI 같은 통신 계층이 필요하다.", "각 노드의 주소 공간이 독립이므로 한 노드 포인터를 그대로 사용해 다른 노드 메모리에 접근할 수 없다.", "이름이 같아도 서로 다른 노드의 변수 값이 자동 공유되지는 않는다."],['주소 공간 분리','명시적 메시지 통신']);
mc(4,6,s3('90','VI 스토리지'),'RAID','속도만 위한 분산 저장','두 디스크에 데이터를 나누어 저장하지만 복제본이나 패리티는 만들지 않는다. 한 디스크 고장 시 데이터 손실 위험이 있는 방식은?',
["RAID 0", "RAID 1", "RAID 5", "RAID 10"],
["RAID 0은 스트라이핑으로 병렬 입출력을 활용하지만 자체 중복성은 제공하지 않는다.", "RAID 1은 미러링으로 복제 사본을 두므로 중복성이 없는 사례와 다르다.", "RAID 5는 분산 패리티를 이용하는 구성으로 패리티를 만들지 않는 사례와 다르다.", "RAID 10은 미러링과 스트라이핑을 결합하므로 무중복 분산 저장과 다르다."],['스트라이핑','RAID 0은 중복성 없음']);
mc(4,7,s3('93','VI 스토리지'),'RAID','미러와 스트라이프 결합','같은 크기의 디스크 4개로 두 개의 미러 쌍을 만들고 그 쌍들 위에 스트라이핑했다. 대표 RAID 수준은?',
["RAID 10", "RAID 0", "RAID 1만 사용", "RAID 0+1"],
["RAID 10은 미러링한 묶음에 스트라이핑을 결합한다. 미러 쌍 구성에 따라 동시 고장 허용 여부가 달라진다.", "RAID 0은 스트라이핑만 하며 먼저 미러 쌍을 만든다는 조건을 충족하지 않는다.", "RAID 1만으로는 미러 쌍들 위에 스트라이핑하는 계층까지 설명하지 못한다.", "RAID 0+1은 먼저 스트라이프 묶음을 만들고 그 묶음을 미러링하는 순서로 사례의 RAID 10과 다르다."],['미러링+스트라이핑','모든 두 디스크 고장을 보장하지 않음']);
mc(4,8,s3('120','VIII 장애 대응'),'가용성 지표','수리 시간 줄이기','MTBF가 같을 때 MTTR을 줄이면 MTBF/(MTBF+MTTR)로 정의한 가용성은 어떻게 되는가?',
['증가한다.','감소한다.','항상 0이다.','MTTR과 무관하다.'],['분자는 같고 분모가 작아지므로 가용성이 증가한다. 신속한 탐지·복구가 영향을 준다.','분모 감소 방향을 반대로 해석한 선택지다.','MTBF가 양수라면 식의 값이 항상 0이 되는 것은 아니다.','식에 MTTR이 포함되므로 복구 시간은 가용성에 영향을 준다.'],['고장 빈도와 복구 시간','가용성 계산']);
mc(4,9,s4('27','II 암호 기술'),'공개키','비밀 수신 메시지의 키','송신자가 수신자만 복호화할 수 있는 암호문을 공개키 방식으로 만들려 한다. 수신자 공개키의 진위는 확인되었다. 사용할 키는?',
["수신자의 공개키", "송신자의 개인키", "송신자의 공개키", "수신자의 개인키를 송신자에게 전달"],
["수신자의 공개키로 암호화한 메시지는 대응 개인키를 가진 수신자가 복호화한다.", "송신자의 개인키를 사용하는 서명은 출처 검증과 관련된다. 수신자 전용 기밀성 암호화 목적과 다르다.", "송신자 공개키로 암호화하면 대응 송신자 개인키가 필요해 수신자 전용 복호화 목적과 다르다.", "개인키는 수신자만 보호해야 한다. 암호화를 위해 상대에게 개인키를 전달하는 것은 공개키 체계의 목적에 맞지 않는다."],['공개키의 신원 확인','개인키 비밀 유지']);
mc(4,10,s4('35–37','II 전자서명·PKI'),'전자서명','발신자와 내용 확인','보고서 수신자가 문서 변경 여부와 서명자의 출처를 검증하려 한다. 전자서명 검증에 사용하는 키는?',
["서명자의 공개키", "서명자의 개인키를 전달받아 검증", "수신자의 공개키", "수신자의 개인키"],
["서명은 서명자의 개인키로 생성하고 대응 공개키로 검증한다. 공개키가 실제 서명자의 것인지 확인해야 한다.", "검증자가 서명자의 개인키를 받으면 서명 위조 능력까지 갖게 된다. 검증에는 공개키를 사용한다.", "서명 생성에 사용한 개인키에 대응하는 공개키여야 한다. 수신자 공개키는 다른 키 쌍이다.", "수신자 개인키는 수신자를 위한 암호문 복호화 등에 쓰이며 타인의 서명 검증키가 아니다."],['서명 생성=개인키','서명 검증=공개키']);
mc(4,11,s4('37','II PKI'),'인증서','공개키의 주인을 확인하기','인증서가 신원 정보와 공개키를 결합하고 인증기관이 서명한다. 인증기관(CA)의 대표 역할은?',
["인증서 발급·서명과 상태 관리", "등록 신청자의 신원 확인 업무만 수행하는 RA", "검증자의 모든 업무 권한 결정", "도메인 이름을 IP 주소로 해석"],
["CA는 검증 절차에 따라 인증서를 발급·서명하고 폐지 등 상태를 관리한다.", "RA는 등록 단계에서 신청자 신원 확인을 지원하는 역할로 CA의 발급·서명 역할과 구분한다.", "인증서는 신원·키 신뢰를 다룬다. 모든 자원에 대한 업무 인가는 서비스의 별도 정책이다.", "도메인 주소 해석은 DNS의 역할이며 CA의 인증서 서명과 다르다."],['신원과 공개키의 결합','발급뿐 아니라 폐지도 관리']);
mc(4,12,s4('89','VI 암호키 관리'),'키 관리','DB와 키를 함께 복사','암호화된 DB 백업 옆에 평문 복호화 키도 놓았다. 이 설계의 가장 큰 문제는?',
["백업 유출 시 데이터와 키가 함께 노출될 수 있다.", "키 길이가 길면 저장 위치와 접근권한은 무관하다.", "백업 파일 이름을 변경하면 키 분리와 동일하다.", "읽기 전용 백업이면 비밀키 노출은 문제가 없다."],
["암호문과 평문 키를 함께 획득하면 암호화 보호 효과가 사라질 수 있다. 키 분리와 접근 통제가 필요하다.", "키 길이는 암호학적 강도 요소지만 키 자체가 노출되면 길이가 길어도 복호화될 수 있다.", "파일 이름 변경은 실제 키 접근권한과 격리를 제공하지 않는다.", "읽기 전용은 변경을 제한할 뿐 읽어서 키를 획득하는 기밀성 위험을 없애지 않는다."],['암호문과 키 분리','키 접근권한 최소화']);
mc(4,13,s4('41–42','II 접근통제'),'MAC','등급 기반 강제 통제','문서 보안 등급과 사용자의 허가 등급을 비교하며 문서 소유자가 임의로 규칙을 완화할 수 없다. 해당 모델은?',
["강제적 접근통제", "임의적 접근통제", "역할 기반 접근통제", "접근통제 목록의 저장 형식만"],
["MAC는 중앙 정책과 보안 표지·허가 수준에 따른 강제 접근통제다.", "DAC는 객체 소유자의 재량으로 권한을 부여하는 모델로 강제 등급 정책과 다르다.", "RBAC는 직무 역할 중심이다. 사례의 핵심인 등급과 강제 정책을 직접 나타내는 모델은 MAC다.", "ACL은 권한 정보를 객체별로 표현하는 방식으로 강제 등급 정책이라는 모델 자체와 구분한다."],['MAC=정책·등급','DAC=소유자 재량']);
mc(4,14,s4('51','III IoT 보안'),'보안 설계','출시 직전 보안 추가','스마트 잠금장치 개발팀이 설계 단계부터 인증·업데이트 검증·개인정보 보호를 요구사항에 반영한다. 가장 잘 설명하는 원칙은?',
["Security by Design", "개발 완료 후 침투 시험만 수행", "운영 중 사고 발생 뒤만 보완", "암호화 라이브러리만 선택하고 위협 분석 생략"],
["Security by Design은 설계부터 보안을 고려하여 제품 생명주기에 반영하는 접근이다.", "완료 후 시험도 필요하지만 설계 초기부터 요구를 반영한다는 Security by Design과 범위가 다르다.", "사후 대응만으로는 초기 아키텍처와 데이터 수집 설계의 위험을 줄이기 어렵다.", "암호화는 일부 통제이며 인증·업데이트·개인정보 처리 전반의 요구 분석을 대신하지 않는다."],['설계 단계의 보안 요구','생명주기 전체 통제']);
mc(4,15,s4('80–81','VI DB 보안'),'DB 보호','서비스 중단에 직접 대응','DB 기밀성·무결성·가용성을 각각 강화한다. 서버 고장에도 조회를 계속 제공하려는 통제와 가장 직접적으로 연결되는 목표는?',
["가용성", "기밀성", "무결성", "부인방지"],
["장애 상황에서도 필요한 서비스를 이용할 수 있게 하는 목표는 가용성이다. DB 이중화와 복구가 관련된다.", "기밀성은 비인가 열람·노출 방지로 서비스 계속 이용이라는 직접 목표와 다르다.", "무결성은 무단 변경·손상을 방지하는 속성이다. 서버 고장에도 이용 가능해야 한다는 핵심은 가용성이다.", "부인방지는 특정 행위 사실을 부정하기 어렵게 하는 속성으로 서비스 지속성과 구분한다."],['보안 목표별 통제 구분','이중화와 복구']);

// 5회차: 클라우드와 조직의 데이터 보호.
mc(5,1,s3('127–128','IX 클라우드'),'클라우드 모델','가상 서버를 임대하기','기업이 가상 머신·네트워크·디스크를 임대하고 게스트 OS와 응용은 직접 설치·운영한다. 서비스 유형은?',
["IaaS", "PaaS", "SaaS", "서버리스 실행 환경만 제공"],
["IaaS는 인프라 자원을 서비스로 제공하며 이 사례에서 이용자가 OS와 응용을 관리한다.", "PaaS는 실행 플랫폼 관리까지 공급자가 담당하는 모델로 이용자가 게스트 OS를 설치하는 사례와 다르다.", "SaaS는 완성된 응용을 서비스로 이용하는 형태다.", "서버리스는 일반적으로 이용자가 개별 게스트 OS 설치·관리를 직접 맡지 않는 추상화와 대비된다."],['IaaS의 책임 범위','OS·응용 관리 주체']);
mc(5,2,s3('128','IX 클라우드'),'PaaS','코드 배포에 집중하기','개발자는 코드와 데이터를 관리하고 공급자가 운영체제와 실행 환경을 제공한다. 가장 가까운 서비스 유형은?',
["PaaS", "IaaS", "SaaS", "직접 구축한 온프레미스"],
["PaaS는 응용 개발·실행 플랫폼을 제공해 이용자가 응용 개발에 집중하도록 한다.", "IaaS는 가상 인프라 제공 중심으로 이용자가 OS·실행 환경을 관리하는 범위가 더 넓다.", "SaaS는 완성 응용 이용 중심이며 직접 코드 배포가 중심인 사례와 구분한다.", "직접 구축 환경은 조직이 운영체제와 플랫폼도 관리하는 경우와 대비된다."],['실행 환경 서비스','책임 분담 확인']);
mc(5,3,s3('129','IX 클라우드'),'배치 모델','민감 업무와 확장 자원 결합','민감 업무는 내부 클라우드에서 운영하고 공개 서비스는 공용 클라우드와 연계한다. 가장 알맞은 배치 모델은?',
["하이브리드 클라우드", "퍼블릭 클라우드만 사용", "프라이빗 클라우드만 사용", "공용 클라우드 두 곳을 쓰는 멀티클라우드만"],
["서로 다른 배치 환경을 연결해 활용하는 하이브리드 클라우드 사례다.", "내부 클라우드가 함께 명시되어 공용 환경만 사용하는 구성과 다르다.", "공용 서비스 환경과의 연계가 있으므로 내부 전용만의 구성이 아니다.", "멀티클라우드는 복수 클라우드 활용을 강조한다. 사례의 핵심은 내부 전용과 공용 환경의 결합이다."],['서로 다른 환경의 연계','데이터 이동 통제']);
mc(5,4,s3('130','IX 가상화'),'하이퍼바이저','호스트 OS 위의 가상화','개인 PC의 운영체제 위에 가상화 프로그램을 설치하고 게스트 OS를 실행했다. 구조로 적절한 것은?',
["호스티드 하이퍼바이저", "베어메탈 하이퍼바이저", "운영체제 커널을 공유하는 컨테이너만", "애플리케이션의 일반 스레드"],
["호스티드 방식은 호스트 OS 위에서 가상화 계층이 동작한다.", "베어메탈은 일반적으로 하이퍼바이저가 하드웨어 위에서 직접 동작한다. 호스트 OS 위 설치와 다르다.", "컨테이너는 일반적으로 호스트 커널을 공유한다. 별도의 게스트 OS를 실행하는 사례와 다르다.", "스레드는 프로세스의 실행 흐름이며 별도 게스트 OS 실행 환경과 다르다."],['Type 1과 Type 2','호스트 OS 유무']);
mc(5,5,s3('134','IX 컨테이너'),'오케스트레이션','원하는 복제 수 유지','운영자가 서비스 복제본 3개를 선언했고 하나가 종료되자 관리 시스템이 새 인스턴스를 배치했다. 대표적으로 담당하는 기능은?',
["컨테이너 오케스트레이션", "컨테이너 이미지 레지스트리만", "일회성 이미지 빌드", "단일 요청의 부하 분산만"],
["오케스트레이션은 배치·상태 감시·복구 등을 통해 선언된 서비스 상태를 유지한다.", "레지스트리는 이미지를 저장·배포하는 저장소로 실행 중 복제 수를 계속 맞추는 제어와 다르다.", "빌드는 실행 이미지를 만드는 과정이며 종료된 인스턴스를 관찰·재배치하지 않는다.", "부하 분산은 요청을 현재 대상에 배분하는 기능으로 실행 인스턴스 생성·복구까지 단독 보장하지 않는다."],['선언한 상태 유지','배치·확장·복구']);
mc(5,6,s3('136','X 분산 처리'),'Hadoop','분산 파일 저장의 역할','대규모 데이터를 여러 노드에 나누어 보관하는 Hadoop의 저장 계층을 찾고 있다. 해당 구성요소는?',
['HDFS','YARN','MapReduce','Hive'],['HDFS는 Hadoop의 분산 파일 저장 계층이다.','YARN은 클러스터 자원 관리와 작업 실행 조정에 관련된다.','MapReduce는 데이터를 분산 계산하는 처리 모델이다.','Hive는 SQL과 유사한 질의로 데이터를 분석하는 계층이다.'],['저장과 처리 분리','HDFS·YARN·MapReduce 역할']);
mc(5,7,s3('121','VIII 고가용성'),'이중화','평상시 한 서버만 처리','주 서버가 요청을 처리하고 대기 서버는 상태를 감시한다. 주 서버 고장 때 대기 서버가 업무를 넘겨받는다. 구성은?',
["Active-Standby", "Active-Active", "RAID 미러링만", "주기적 백업만"],
["Active-Standby는 평상시 활성 서버와 대기 서버를 두며 장애 시 역할을 전환한다.", "Active-Active는 평상시에도 여러 서버가 요청을 처리하는 구성으로 대기 서버만 있는 사례와 다르다.", "디스크 미러링은 저장 사본을 관리한다. 서버 상태 감지와 업무 역할 전환 전체가 아니다.", "백업은 복구 사본을 확보하는 활동이며 자동 역할 전환 대기 서버 구성과 구분한다."],['Failover','대기 자원과 상태 동기화']);
mc(5,8,s3('124','VIII 재해 복구'),'DR 준비도','복구 준비가 적은 대체 공간','재해 복구 장소에 공간과 전력은 마련했지만 서버와 최신 데이터는 별도로 반입해야 한다. 대표적인 유형은?',
['Cold Site','실시간 미러 사이트','Active-Active 즉시 전환','항상 RTO 0인 사이트'],['Cold Site는 인프라 기반만 준비된 형태로 장비·데이터 준비 때문에 일반적으로 복구 시간이 더 길다.','미러 사이트는 시스템·데이터가 높은 수준으로 동기화되어 있는 형태다.','장비 반입이 필요한 상황은 즉시 처리 중인 Active-Active와 다르다.','RTO 0은 준비 없이 달성할 수 없으며 유형만으로 보장되지 않는다.'],['준비 수준과 복구 시간','비용·복구 목표 절충']);
mc(5,9,s4('53','III 클라우드 보안'),'가상화 보안','공유 기반의 침해 영향','한 물리 서버의 하이퍼바이저가 침해되었다. 여러 VM을 운영하는 조직이 특히 우려해야 할 점은?',
["공유 가상화 기반을 사용하는 여러 VM으로 영향이 확대될 가능성", "게스트 계정만 관리하면 하이퍼바이저 점검은 불필요", "외부 경계 방화벽만 있으면 공유 기반 취약점이 없어짐", "VM 이름이 다르면 기반 보안 영향도 분리됨"],
["하이퍼바이저는 여러 VM의 공유 신뢰 기반이므로 취약점이 여러 게스트의 격리에 영향을 줄 수 있다.", "게스트 계정 통제와 공유 가상화 기반 보안은 별도 계층이므로 하이퍼바이저 패치·점검도 필요하다.", "외부 방화벽은 일부 경로를 통제하지만 하이퍼바이저 취약점과 내부 공격 경로를 자동 제거하지 않는다.", "표시 이름이 달라도 공유 기반의 격리 취약점은 여러 VM에 영향을 줄 수 있다."],['공유 신뢰 기반','격리와 패치']);
mc(5,10,s4('81','VI DB 접근통제'),'데이터 공개 범위','일부 열만 분석가에게 제공','분석가는 고객의 지역과 주문 합계만 필요하고 연락처는 볼 필요가 없다. 적절한 DB 접근 설계는?',
["필요한 열의 뷰에만 조회 권한 부여", "원본 테이블에 조회 권한을 유지하면서 뷰도 제공", "연락처를 UI에서만 숨기고 API는 전체 열 반환", "모든 분석가에게 DB 관리자 역할 부여"],
["뷰로 필요한 범위를 제공하고 원본 접근권한도 제한해야 불필요한 정보 노출을 줄인다.", "뷰를 만들어도 원본 테이블을 계속 조회할 수 있다면 제한을 우회할 수 있다.", "화면 표시만 숨겨도 API 응답에 민감 열이 포함되면 이용자가 그 값을 얻을 수 있다.", "관리자 역할은 필요한 범위를 훨씬 넘으므로 최소 권한 원칙에 어긋난다."],['뷰와 권한의 결합','필요 데이터만 제공']);
mc(5,11,s4('83','VI DB 암호화'),'암호화 설계','암호화 도입 전 점검','민감 열을 암호화하면서 조회 지연이 늘어날 수 있다. 설계 단계의 타당한 검토는?',
['암호화 대상·검색 영향·키 관리와 성능을 함께 검토','암호화하면 인덱스·성능 영향은 항상 없음','키를 소스 코드에 고정하여 검토 생략','암호화 후 권한 관리를 모두 제거'],['암호화 범위와 검색·인덱스 영향, 키 수명주기, 성능을 함께 검토해야 보안과 업무 요구를 맞춘다.','암호화 방식에 따라 검색 방식과 성능이 달라질 수 있어 무영향으로 단정할 수 없다.','키 하드코딩은 노출·교체 위험을 만들며 검토를 대신하지 못한다.','암호화는 접근통제의 대체가 아니므로 권한 관리는 계속 필요하다.'],['대상·성능·키 관리','통제의 상호 보완']);
mc(5,12,s4('89','VI 암호키 관리'),'키 수명주기','암호문만 살아 있는 복구','백업 데이터는 온전하지만 유일한 복호화 키가 소실되었다. 예방 설계로 적절한 것은?',
["키의 안전한 백업과 복구 절차도 시험한다.", "데이터 사본 수만 늘리고 키 복구는 제외", "사용한 암호 알고리즘 이름만 보관", "평문 키를 동일 백업에 제한 없이 포함"],
["데이터 복구에는 필요한 키도 있어야 한다. 키 백업은 접근을 제한하고 복구 절차를 검증해야 한다.", "여러 암호문 사본이 있어도 필요한 키가 모두 소실되면 원문 복구가 어려울 수 있다.", "알고리즘은 공개될 수 있으며 그 이름을 안다고 비밀키를 재생성할 수 있는 것은 아니다.", "키 복구는 필요하지만 암호문과 키를 누구나 같이 읽도록 두면 기밀성 보호가 무너진다."],['데이터와 키의 복구','복구 시험']);
mc(5,13,s4('46','III APT'),'지속 공격','긴 시간 내부를 탐색한 흔적','특정 연구기관에서 초기 감염 후 내부 시스템 탐색과 장기간의 자료 수집·유출이 확인됐다. 설명에 가장 가까운 공격은?',
["APT", "단일 시점의 서비스 거부 공격", "파일 암호화 후 금전 요구", "단순 포트 상태 점검만"],
["APT는 특정 목표에 대해 여러 기법을 결합하여 장기간 지속적으로 침투·수집하는 공격 양상이다.", "서비스 거부는 이용을 방해하는 공격이다. 사례의 표적·장기 침투·수집이라는 양상을 모두 설명하지 못한다.", "랜섬웨어의 대표 양상으로 자료를 장기 수집·유출하는 APT 설명과 구분한다.", "포트 점검은 탐색 단계 일부일 수 있으나 지속 침투·수집·유출 전체를 설명하지 못한다."],['표적·지속성','다단계 방어']);
mc(5,14,s4('49','III 악성코드'),'자원 탈취','알 수 없는 채굴 프로세스','사용자 동의 없이 채굴 프로그램이 실행되어 CPU와 전력을 소비한다. 가장 적절한 용어는?',
["크립토재킹", "랜섬웨어", "스파이웨어의 정보 수집만", "정상적으로 승인된 분산 계산"],
["크립토재킹은 다른 사람의 컴퓨팅 자원을 무단으로 이용하여 암호화폐를 채굴하는 행위다.", "랜섬웨어는 접근을 막고 복구 대가를 요구한다. 사례는 무단 채굴을 위한 자원 탈취다.", "정보 수집이 핵심인 스파이웨어와 달리 사례는 CPU를 채굴에 소비하는 행위가 핵심이다.", "승인된 작업이면 무단 자원 사용과 구분된다. 이 사례는 사용자 동의가 없다고 명시했다."],['동의 없는 자원 사용','프로세스·자원 모니터링']);
mc(5,15,s4('59','IV 위험관리'),'위험 평가','같은 취약점의 우선순위','동일한 취약점이 공개 결제 서버와 격리된 실험 서버에 있다. 대응 순위를 정할 때 타당한 관점은?',
["자산 가치·노출·영향과 기존 통제를 함께 평가", "기술적 심각도 점수가 같으면 업무 맥락 없이 같은 순위", "외부 노출 여부만 비교하고 자산 영향은 제외", "기존 통제가 있으면 잔여 위험 평가 없이 수용"],
["위험은 취약점뿐 아니라 자산 중요도, 위협·노출과 기존 통제에 따른 실제 영향을 함께 고려한다.", "기술적 점수가 같아도 업무 중요도와 공격 가능 경로가 달라 실제 위험 우선순위가 달라질 수 있다.", "노출은 중요하지만 중요한 내부 자산의 피해 영향 등 다른 요소도 함께 평가해야 한다.", "통제를 적용한 뒤에도 잔여 위험이 남을 수 있어 평가·승인 없이 자동 수용해서는 안 된다."],['위험과 취약점은 다름','업무 영향 반영']);


// 6회차: 장애 대응과 안전한 운영 변경.
mc(6,1,s3('123','VIII 장애 대응'),'장애 처리','고장 난 구성요소만 분리','운영팀이 실패한 저장 노드로의 요청을 차단하고 정상 노드가 계속 처리하도록 했다. 이 단계의 목적은?',
["장애 격리", "장애 탐지", "장애 원인 진단", "장애 복구 완료 판정"],
["장애 격리는 문제가 난 부분을 분리해 영향이 정상 구성요소로 확산되는 것을 제한한다.", "장애 탐지는 이상 상태를 알아내는 단계다. 사례는 이미 확인한 실패 노드의 경로를 분리했다.", "원인 진단은 왜 실패했는지 규명하는 단계다. 요청 차단은 영향 확산을 막는 격리 활동이다.", "복구 완료는 정상 상태 회복을 검증하는 단계다. 고장 노드를 분리했다고 그 노드가 복구된 것은 아니다."],['탐지→진단→격리→복구','확산 범위 제한']);
mc(6,2,s3('121','VIII 고가용성'),'이중화 용량','한 노드가 모든 요청을 받으면','동일 사양의 두 Active-Active 서버가 각각 최대 처리 용량의 70%를 사용 중이다. 한 대 장애 때 나머지 한 대로 전체 요청을 보내려 한다. 가장 타당한 검토는?',
["남은 서버에 140% 부하가 몰릴 수 있으므로 여유 용량 또는 부하 제한이 필요하다.", "두 서버에 절반씩 처리하므로 장애 후에도 각 서버 부하는 같다.", "정상 시 평균 응답 시간만으로 장애 용량을 판단한다.", "헬스 체크 간격을 줄이면 부족한 처리 용량도 해결된다."],
["부하가 동일하고 한 대로 모두 이전되면 기존 두 대의 합인 140%가 요구된다. 이중화는 용량 설계도 필요하다.", "한 서버가 사라지면 그 서버가 받던 요청도 나머지로 이동하므로 정상 시의 분산 비율을 유지할 수 없다.", "정상 운영 지표만으로 장애 후 최대 집중 부하를 감당하는지 보장하지 못한다.", "빠른 탐지는 전환 시간을 줄일 수 있지만 물리적인 처리 용량 부족 자체를 해결하지 않는다."],['정상 시와 장애 시 용량','과부하 방지']);
mc(6,3,s3('120','VIII 재해 복구'),'RTO·RPO','복구 시험 결과 판정','목표 RTO 60분, RPO 5분이다. 시험에서 40분 만에 서비스를 열었으나 12분 전 데이터까지만 복원했다. 판정은?',
["RTO는 충족하고 RPO는 미충족", "RTO와 RPO 모두 충족", "RTO만 미충족", "목표를 합한 65분보다 작으면 모두 충족"],
["복구 시간 40분은 60분 이내지만 손실 구간 12분은 허용 5분보다 길다. 두 목표를 따로 비교해야 한다.", "데이터 손실 구간 12분이 허용 5분을 넘겨 RPO는 미충족이다.", "실제 복구 40분은 허용 60분 이내다. 초과한 것은 데이터 시점 목표다.", "두 목표는 다른 차원의 요구이므로 합산한 시간 하나로 충족 여부를 판정할 수 없다."],['복구 시간과 데이터 시점 분리','목표 대비 검증']);
mc(6,4,s3('123–124','VIII 재해 복구'),'복구 사본','같은 건물의 두 서버','동일 건물 안 두 서버에 데이터를 복제했다. 광역 정전·화재로 건물을 이용하지 못하는 위험에 추가로 필요한 것은?',
["분리된 재해 복구 위치와 복구 절차", "같은 랙에 서버만 추가", "같은 건물 안 복제 빈도만 높임", "장애 감지 주기만 단축"],
["같은 위치의 복제는 공통 재해를 함께 겪을 수 있다. 지리적·운영적 분리와 실제 복구 절차를 고려해야 한다.", "같은 랙은 광역 전원·건물 피해를 공유할 수 있어 위치 공통 위험을 해소하지 못한다.", "복제 빈도는 데이터 시점에 영향을 주지만 전체 건물에 접근하지 못하는 위험을 해결하지 않는다.", "감지가 빨라도 사용할 독립 복구 자원과 절차가 없으면 서비스를 재개할 수 없다."],['공통 원인 장애','HA와 DR의 범위 차이']);
mc(6,5,s3('93','VI 스토리지'),'가상 테이프','기존 백업 인터페이스 유지','기존 백업 소프트웨어가 테이프 장치로 인식하도록 디스크 저장소를 제공한다. 관련 기술은?',
["VTL", "DAS", "디스크 스트라이핑", "원격 블록 복제"],
["VTL은 디스크 기반 저장공간을 가상 테이프 라이브러리처럼 제공하여 기존 백업 체계와 연계한다.", "DAS는 서버에 직접 연결된 저장장치 구조다. 테이프 인터페이스를 가상 제공한다는 설명과 다르다.", "스트라이핑은 블록을 여러 디스크에 분산하는 방식으로 테이프 장치처럼 보이는 인터페이스를 뜻하지 않는다.", "원격 복제는 다른 위치의 데이터 사본 유지 방식이며 테이프 라이브러리 에뮬레이션 자체와는 다르다."],['가상 테이프 라이브러리','물리 저장매체와 제공 인터페이스 구분']);
mc(6,6,s3('162','XII 서비스 품질'),'QoS','음성 패킷의 도착 간격','음성 통화 중 평균 지연은 낮지만 패킷 도착 간격이 들쭉날쭉해 재생이 불안정하다. 직접 관련 지표는?',
["지터", "평균 지연", "가용 대역폭", "패킷 손실률만"],
["지터는 패킷 지연의 변동으로 일정 간격 재생이 필요한 음성·영상 품질에 영향을 준다.", "평균 지연은 도착까지 걸린 시간의 평균이며 시간마다 달라지는 변동 폭과 구분해야 한다.", "대역폭은 전송 가능량으로 도착 간격의 변동 자체를 나타내는 지표는 아니다.", "손실률은 누락된 패킷 비율이다. 누락이 없어도 지연 변동으로 재생이 불안정할 수 있다."],['평균 지연≠지터','실시간 서비스 품질']);
mc(6,7,s3('162','XII 서비스 품질'),'트래픽 제어','버스트를 완만하게 보내기','순간적으로 몰린 전송을 버퍼에 담고 일정한 속도로 내보내려 한다. 이 동작에 가까운 것은?',
["트래픽 셰이핑", "초과 트래픽을 즉시 표시·폐기하는 폴리싱", "우선순위 큐에서 고우선 요청만 먼저 처리", "혼잡과 무관하게 패킷 TTL 증가"],
["셰이핑은 트래픽을 지연·버퍼링해 전송률을 조절한다. 버퍼 용량에 따른 한계도 있다.", "폴리싱은 초과 트래픽에 표시·폐기 정책을 적용한다. 버퍼링해서 완만하게 보내는 셰이핑과 다르다.", "우선순위 큐는 서비스 순서를 정하지만 그 자체로 전체 송출률을 일정하게 만드는 것은 아니다.", "TTL은 홉 제한이며 트래픽의 순간 전송률을 평탄화하지 않는다."],['셰이핑=지연 조절','폴리싱=초과 정책 적용']);
mc(6,8,s3('178–180','XIV TCP'),'TCP 흐름 제어','수신 버퍼 보호','수신자의 애플리케이션 처리가 느려 버퍼가 찼다. TCP가 송신량을 조절하도록 알리는 정보는?',
["수신 윈도 크기", "혼잡 윈도만", "IP TTL", "TCP 체크섬"],
["수신 윈도는 수신자가 받아들일 수 있는 양을 알리는 흐름 제어 정보다. 네트워크 혼잡 제어와 구분한다.", "혼잡 윈도는 주로 네트워크 혼잡 상황에 따른 송신 제어다. 수신자가 광고하는 버퍼 여유는 수신 윈도다.", "TTL은 패킷의 전달 홉 수를 제한하는 IP 필드다.", "체크섬은 오류 검출에 쓰이며 수신 버퍼 용량을 알리지 않는다."],['흐름 제어=수신자 보호','혼잡 제어=네트워크 보호']);
mc(6,9,s4('69–70','V 시큐어 코딩'),'SQL 삽입 방지','문자열 결합 쿼리의 수정','사용자 입력을 SQL 조건 문자열에 이어 붙이는 코드를 고친다. 값이 SQL 구조를 바꾸지 못하도록 하는 핵심 방법은?',
["고정된 SQL과 바인딩 매개변수를 사용", "SQL 예약어를 일부 금지하는 목록만 사용", "클라이언트 입력창에서만 검사", "DB 접속 계정 권한만 줄이고 문자열 결합 유지"],
["PreparedStatement 등 매개변수 바인딩으로 SQL 구조와 입력값을 분리한다. 식별자 등 동적 구조는 별도 허용 목록이 필요하다.", "금지 목록은 누락과 해석 차이가 생길 수 있어 값 바인딩에 의한 구조 분리를 대체하지 못한다.", "클라이언트 검사는 우회 가능하므로 서버의 실제 쿼리 구성도 안전해야 한다.", "최소 권한은 피해를 줄이지만 입력이 SQL 구조를 바꾸는 결함 자체를 해결하지 않는다."],['코드와 데이터 분리','값 바인딩']);
mc(6,10,s4('70–71','V 시큐어 코딩'),'XSS','댓글이 브라우저 코드가 된다','댓글을 HTML에 그대로 삽입하여 다른 이용자의 브라우저에서 스크립트가 실행됐다. 가장 직접적인 방어는?',
["출력 문맥에 맞는 인코딩 또는 안전한 텍스트 렌더링", "DB 저장 데이터 암호화", "SQL 매개변수 바인딩만", "웹 전송 구간 TLS 적용만"],
["출력 데이터를 실행 가능한 HTML·스크립트로 해석하지 않게 처리해야 한다. HTML 허용 시 검증된 정화도 필요하다.", "저장 암호화는 원문을 읽을 수 없게 보호하는 통제로 출력한 데이터가 브라우저 코드로 실행되는 결함과 다르다.", "SQL 바인딩은 DB 쿼리 구조를 보호한다. 브라우저에 넣는 출력의 HTML 해석은 별도로 통제한다.", "TLS는 안전한 전송을 제공하지만 악성 스크립트가 포함된 내용을 안전하게 전달할 수도 있다."],['저장형 XSS','출력 위치별 안전한 처리']);
mc(6,11,fileAPI,'Java 파일 API','경로 객체와 실제 파일','Java에서 new File("없는파일.txt")가 정상 완료되었다. 생성된 참조에 대한 올바른 설명은?',
['경로 객체가 만들어지며 파일 존재 여부는 별도로 확인한다.','대상이 없으므로 참조는 자동으로 null이다.','생성자만으로 빈 파일이 디스크에 반드시 생긴다.','참조가 있으므로 delete()는 반드시 성공한다.'],['File은 추상 경로를 표현한다. 실제 대상 존재 여부와 객체 생성은 다르며 exists() 등으로 별도 확인한다.','존재하지 않는 경로도 File 객체로 표현되므로 null이라고 볼 수 없다.','File 생성 자체는 실제 파일 생성과 다르다. 파일 생성에는 별도 작업이 필요하다.','delete()는 성공 여부를 반환하며 권한·대상 상태 등에 따라 실패할 수 있다.'],['객체 null과 파일 존재는 다름','삭제 결과 확인']);
mc(6,12,s4('69','V 시큐어 SDLC'),'보안 개발','요구사항 단계의 보안','새 서비스에서 보호할 자산과 예상 위협을 식별하고 보안 요구를 도출했다. 보안 개발 생명주기의 어느 활동인가?',
["요구사항 정의 단계의 보안 분석", "구현 단계의 정적 코드 분석", "시험 단계의 동적 보안 검증", "운영 단계의 침해 사고 조사"],
["시큐어 SDLC의 초기 단계에서 자산·위협·영향을 분석하여 필요한 보안 요구사항을 도출한다.", "정적 분석은 만들어진 코드의 결함을 분석하는 활동이다. 사례는 코딩 전 보호 목표와 위협을 정의한다.", "동적 검증은 실행 환경의 동작을 시험한다. 초기 요구 도출 단계와 구분한다.", "사고 조사는 실제 사건 증거를 분석하는 운영 활동으로 새 서비스 요구 도출과 다르다."],['초기 보안 요구','설계·코딩·검증과 연계']);
mc(6,13,s4('97','VII 시스템 보안'),'공격 표면','사용하지 않는 서비스','서버 이미지에 업무에서 쓰지 않는 원격 접속 데몬이 기본 실행 중이다. 합리적인 조치는?',
["의존성을 확인한 뒤 불필요한 서비스를 중지하고 접근을 제한", "포트 번호만 변경하고 동일하게 공개", "데몬 실행은 유지하고 사용자 안내만 강화", "외부 방화벽이 있으니 내부 노출은 점검하지 않음"],
["불필요한 서비스를 줄이면 공격 표면을 줄일 수 있다. 업무 의존성을 먼저 확인해야 한다.", "포트 변경은 자동 탐색을 일부 혼동시킬 수 있지만 취약 서비스와 불필요한 접근 경로를 제거하지 않는다.", "안내는 관리적 통제지만 실행 중인 불필요한 서비스를 줄이는 기술적 조치를 대체하지 않는다.", "내부 위협과 우회 경로도 존재하므로 외부 방화벽만으로 서비스 점검을 생략할 수 없다."],['필요 기능만 활성화','변경 영향 검토']);
mc(6,14,s4('89','VI 키 관리'),'직무 분리','한 사람이 모든 키 업무 수행','한 운영자가 DB 백업과 복호화 키 승인·반출을 모두 단독 수행한다. 내부 오남용 위험을 줄일 원칙은?',
["직무 분리와 제한된 승인 권한", "관리자 한 명의 비밀번호만 길게 설정", "사후 로그만 남기고 모든 승인권을 한 사람에게 유지", "키를 숨긴 파일명으로 같은 운영자가 관리"],
["민감 업무를 나누고 키 접근을 승인·기록하면 한 사람이 통제를 우회할 위험을 줄인다.", "강한 비밀번호는 외부 추측을 줄일 수 있지만 한 사람의 과도한 업무 권한 집중은 남는다.", "로그는 탐지·감사에 유용하지만 승인 분리 없이 단독 행위를 예방하는 통제는 부족하다.", "파일명 은닉은 직무 분리나 승인 권한 통제를 구현하지 않는다."],['Separation of Duties','최소 권한·감사']);
mc(6,15,s4('62','IV 개인정보 보호'),'데이터 생명주기','학습용 데이터 보관','서비스 분석 목적이 끝난 개인정보의 보존 필요성을 검토한다. 일반적인 보호 원칙으로 적절한 것은?',
["목적·보유 필요·별도 보존 근거를 검토해 불필요한 자료를 안전하게 파기", "보관 비용이 낮으면 활용 목적 없이 계속 보유", "암호화했다면 보유 필요 검토 생략", "업무 DB에서만 삭제하고 별도 사본은 검토 제외"],
["개인정보는 목적과 보유 필요를 검토하며 불필요한 보관을 줄인다. 별도 보존 근거가 있는 자료는 분리·통제한다.", "비용이 낮아도 불필요한 개인정보 보유는 노출 위험을 만들므로 목적과 필요성을 검토해야 한다.", "암호화는 안전성 통제이며 보유 목적과 필요성 검토를 대신하지 않는다.", "파기·보존 정책은 관련 사본과 백업에도 적절히 반영되어야 하며 한 위치 삭제만으로 검토가 끝나지 않는다."],['목적 제한','보존과 파기 정책']);

// 7회차: 전송·응용 계층과 신뢰 검증.
mc(7,1,s3('180','XIV TCP'),'TCP 연결','연결 시작 패킷','클라이언트가 TCP 연결 수립을 처음 요청할 때 대표적으로 사용하는 제어 플래그는?',
["SYN", "FIN", "ACK만", "RST"],
["SYN은 초기 순서번호 동기화와 연결 수립 과정에 사용한다.", "FIN은 송신 종료 의사를 알리는 플래그로 최초 연결 요청과 다르다.", "ACK는 확인 응답을 나타낸다. 최초 연결 수립 요청은 SYN을 이용한다.", "RST는 연결 재설정·거절 등에 사용되며 정상 최초 연결 요청과 다르다."],['SYN→SYN/ACK→ACK','연결 수립과 종료']);
mc(7,2,s3('178–180','XIV TCP'),'TCP 데이터','한 번 보냈으니 한 번 받는다?','프로그램이 TCP로 두 번 send했다. 상대 프로그램의 recv 호출 횟수와 경계에 대한 올바른 설명은?',
['TCP는 바이트 스트림이므로 응용이 메시지 경계를 정해야 한다.','recv는 항상 send와 같은 경계로 두 번 반환한다.','TCP는 반드시 각 호출을 하나의 UDP 패킷으로 바꾼다.','순서가 보장되면 길이 정보는 항상 불필요하다.'],['TCP는 순서 있는 바이트 스트림을 제공하며 send 호출 단위가 응용 메시지 경계로 보존되는 것은 아니다.','수신 단위는 버퍼와 도착 상황에 달라질 수 있어 호출 경계 대응을 보장하지 않는다.','TCP와 UDP는 별도 프로토콜이며 호출 단위를 UDP로 변환하지 않는다.','순서 보장과 메시지 경계 구분은 다르므로 길이·구분자 등 설계가 필요하다.'],['바이트 스트림','길이·구분자 기반 프레이밍']);
mc(7,3,s3('185','XIV UDP'),'응용 신뢰성','UDP 위에서 순서 복구','UDP 센서 메시지가 순서 없이 도착할 수 있다. 수신자가 측정 순서를 구분하도록 응용이 추가할 정보는?',
["메시지 순서번호 또는 측정 시각", "수신 완료한 순서만 저장", "UDP 목적지 포트만으로 측정 순서 판단", "데이터그램 길이만으로 순서 추정"],
["응용 순서번호나 측정 시각으로 도착 순서와 측정 순서를 구분할 수 있다. 누락 처리 정책도 별도로 정한다.", "수신 순서는 네트워크 지연·재정렬 때문에 실제 측정 순서와 다를 수 있다.", "목적지 포트는 응용을 구분하지만 메시지의 시간적 순서를 나타내지 않는다.", "크기가 같거나 크기와 시각이 무관할 수 있어 길이로 측정 순서를 복원할 수 없다."],['전송 순서와 사건 시각','응용 계층 보완']);
mc(7,4,s3('194','XV 응용 계층'),'DNS','이름 해석의 단계','브라우저가 URL의 호스트 이름에 대응하는 주소를 조회한다. 이 작업을 담당하는 체계는?',
["DNS", "ARP", "DHCP", "라우팅 프로토콜 OSPF"],
["DNS는 호스트 이름 등 도메인 레코드를 조회하는 분산 이름 체계다.", "ARP는 로컬 링크의 IP와 MAC 대응을 알아낸다. URL 호스트 이름 조회와 다르다.", "DHCP는 단말의 주소·네트워크 설정을 제공하는 데 쓰며 임의 도메인 레코드 조회와 다르다.", "OSPF는 네트워크 경로를 교환·계산하며 도메인 이름을 조회하지 않는다."],['이름→주소 레코드','DNS와 ARP 구분']);
mc(7,5,s3('194','XV 응용 계층'),'전자우편','발신 서버 간 전달','발신 메일을 다른 메일 서버로 전달하는 대표 프로토콜은?',
['SMTP','IMAP','POP3','SNMP'],['SMTP는 메일 발신·서버 간 전송에 쓰인다.','IMAP은 서버의 메일함을 조회·동기화하는 데 쓰인다.','POP3는 수신 메일을 가져오는 데 쓰이며 서버 간 발신 전송과 다르다.','SNMP는 네트워크 장비 관리용이다.'],['메일 전송과 수신 구분','SMTP·IMAP·POP']);
mc(7,6,s3('194','XV 응용 계층'),'HTTP','요청 대상 없음','웹 서버는 정상 동작하지만 사용자가 요청한 경로의 자원을 찾지 못했다. 일반적인 HTTP 응답은?',
['404','200','301','500'],['404는 요청 자원을 찾을 수 없음을 나타내는 클라이언트 오류 범주 응답이다.','200은 요청의 성공 응답이다.','301은 영구적인 다른 위치로의 이동을 알리는 리다이렉션이다.','500은 서버 내부 오류이며 자원을 찾지 못한 상황의 대표 응답과 다르다.'],['2xx 성공','3xx 이동','4xx 요청 문제','5xx 서버 문제']);
mc(7,7,s3('194','XV 응용 계층'),'네트워크 관리','장비 상태 수집','스위치와 라우터의 상태·통계 정보를 관리 시스템에서 조회하려 한다. 대표적으로 관련된 프로토콜은?',
['SNMP','SMTP','ARP','ICMP만으로 모든 관리 대체'],['SNMP는 네트워크 장비의 관리 정보를 수집·조회하는 프로토콜이다.','SMTP는 메일 전송용이다. 약어가 비슷해도 목적이 다르다.','ARP는 이웃의 MAC 주소 확인용이며 장비 관리 정보 전체를 제공하지 않는다.','ICMP는 오류·진단 메시지에 쓰이지만 모든 장비 관리 정보를 대체하지 않는다.'],['관리 프로토콜','약어 구분']);
mc(7,8,s3('160','XII 네트워크 계층'),'ICMP','라우터의 오류 알림','라우터가 IP 패킷의 전달 불가 상황을 원래 송신 측에 알리려 한다. 관련된 프로토콜은?',
["ICMP", "TCP ACK", "HTTP 404", "ARP 응답"],
["ICMP는 IP 전달 중 오류와 진단 정보를 전달하는 데 사용된다.", "TCP ACK는 연결의 바이트 수신 확인 정보다. IP 전달 오류 통지와 구분한다.", "HTTP 404는 응용 자원을 찾지 못한 웹 응답으로 라우터의 IP 오류 메시지가 아니다.", "ARP 응답은 링크 주소 대응 정보를 제공하며 IP 전달 불가 상황의 통지와 다르다."],['IP 보조 오류 통지','응용 응답과 구분']);
mc(7,9,s4('107·113','VIII 보안 프로토콜'),'TLS','전송 암호화의 보호 범위','브라우저와 웹 서버 사이에 TLS를 적용했다. TLS만으로 보장한다고 볼 수 없는 것은?',
['서버에 저장된 모든 데이터의 자동 암호화','전송 구간의 기밀성 보호','전송 데이터 무결성 보호','적절한 인증서 검증을 통한 서버 신원 확인'],['TLS는 통신 구간을 보호한다. 서버가 저장하는 데이터의 암호화·접근통제는 별도 설계해야 한다.','기밀성 보호는 TLS의 주요 목적 중 하나다.','무결성 검증 역시 TLS 보호 기능에 포함된다.','인증서와 신뢰 경로 검증을 올바르게 수행하면 서버 인증에 활용된다.'],['전송 중과 저장 시 보호 구분','TLS가 응용 취약점을 모두 해결하지 않음']);
mc(7,10,s4('37·115','II PKI·VIII TLS'),'인증서 검증','다른 호스트의 인증서','접속하려는 서비스 도메인과 인증서의 대상 이름이 다르다. 안전한 처리 원칙은?',
["대상 이름과 신뢰 검증 실패를 확인하고 연결을 중단·수정한다.", "인증서 유효기간만 맞으면 연결 허용", "신뢰된 CA 서명만 있으면 대상 이름 비교 생략", "암호 스위트가 강하면 인증서 검증 실패를 무시"],
["인증서의 키가 연결하려는 주체의 것인지 확인해야 한다. 이름 불일치는 설정 오류나 잘못된 대상 접속을 나타낼 수 있다.", "유효기간이 맞아도 접속하려는 도메인의 인증서인지 확인해야 의도한 상대를 인증할 수 있다.", "신뢰된 CA가 발급한 다른 사이트의 인증서일 수 있어 대상 이름도 함께 검증해야 한다.", "강한 암호화 알고리즘을 써도 상대의 신원이 잘못되면 중간자 위험을 해결하지 못한다."],['서버 이름과 인증서 대상','암호화와 상대 인증']);
mc(7,11,s4('32·35','II 인증'),'생체 인증','인증 요소 분류','지문을 제시하여 사용자를 확인하는 방식은 어떤 범주의 인증 요소인가?',
["생체·고유 특성", "지식 요소", "소지 요소", "서비스별 권한"],
["지문은 사용자의 신체적 특성을 이용하는 생체 인증 요소다.", "비밀번호·PIN처럼 기억하는 정보가 지식 요소다. 지문은 사용자의 생체 특성이다.", "토큰·카드 등 가지고 있는 물체를 증명하는 것은 소지 요소다.", "서비스 권한은 인증 후 어떤 작업을 허용할지를 정하는 인가 정보다."],['아는 것·가진 것·고유한 것','인증과 인가 구분']);
mc(7,12,s4('42','II 접근통제'),'접근통제 행렬','객체마다 권한 열거','파일마다 누가 읽기·쓰기를 할 수 있는지를 목록으로 관리한다. 객체 중심의 표현 방식은?',
["ACL", "Capability 목록", "역할 목록만", "보안 등급 목록만"],
["ACL은 객체별로 주체와 허용 연산을 기록하는 접근통제 목록이다.", "Capability 목록은 주체를 기준으로 접근 가능한 객체와 권한을 표현하는 방식으로 대비된다.", "역할 목록은 권한 묶음의 분류이며 객체마다 허용 주체·연산을 직접 열거한 ACL 표현과 다르다.", "등급 목록은 강제 통제의 기준 정보로 객체별 개별 주체 권한 목록 자체는 아니다."],['객체 중심 ACL','주체 중심 Capability']);
mc(7,13,s4('42','II 접근통제'),'보안 모델','기밀성과 무결성 구분','보안 모델을 비교하면서 Bell-LaPadula가 주로 다루는 보호 목표를 찾는다. 적절한 것은?',
["기밀성", "무결성", "가용성", "부인방지"],
["Bell-LaPadula는 보안 등급에 따른 정보 흐름으로 기밀성을 보호하는 모델이다.", "Biba 등은 무결성 보호 중심 모델이다. Bell-LaPadula의 주된 목표인 기밀성과 대비된다.", "가용성은 서비스 이용 가능성으로 BLP의 등급 기반 정보 흐름 제한이 주로 다루는 목표가 아니다.", "부인방지는 행위 사실의 부정을 어렵게 하는 속성으로 BLP의 중심 목표와 다르다."],['BLP=기밀성','Biba=무결성']);
mc(7,14,s4('64','IV 보안 표준'),'약점 분류','여러 제품에 반복되는 원인','서로 다른 제품에서 발생하는 SQL 삽입 같은 소프트웨어 약점의 공통 유형을 분류하고 싶다. 알맞은 체계는?',
['CWE','CVE 개별 ID만','CVSS 점수만','MTTR'],['CWE는 소프트웨어 약점 유형을 분류하는 체계이므로 공통 원인을 묶는 데 적합하다.','CVE는 특정 공개 취약점 한 건을 식별하는 기록이다.','CVSS는 심각도 평가 체계로 약점 유형 이름의 분류를 대신하지 않는다.','MTTR은 평균 복구 시간 지표로 보안 약점 분류와 다르다.'],['유형과 개별 사례','CWE와 CVE']);
mc(7,15,s4('51','III 보안 위협'),'악성 광고','정상 사이트의 광고 경로','정상 웹사이트에 표시된 외부 광고망의 악성 광고를 통해 이용자가 악성코드 배포 경로에 노출됐다. 관련 용어는?',
["멀버타이징", "스피어 피싱", "파밍", "랜섬웨어"],
["멀버타이징은 광고 생태계의 광고 콘텐츠·연결을 악용해 악성코드를 유포하는 방식이다.", "스피어 피싱은 특정 대상을 겨냥한 기만 메시지 등이 중심이다. 여기서는 광고망을 통한 유포 경로가 핵심이다.", "파밍은 주소 해석·접속 정보를 조작해 가짜 사이트로 유도한다. 악성 광고 유포와 구분한다.", "랜섬웨어는 감염 이후 파일 등을 인질로 대가를 요구하는 악성코드 유형이다. 광고 기반 유포 경로의 명칭은 아니다."],['정상 사이트도 외부 콘텐츠 영향','광고 경로의 신뢰']);

// 8회차: 분산 운영과 보안 경계.
mc(8,1,s3('215','XVII 네트워크 가상화'),'SDN','경로 제어와 패킷 전달','네트워크 정책·경로 판단을 컨트롤러에서 관리하고 장비는 전달 규칙에 따라 패킷을 처리한다. 핵심 설계는?',
["제어 평면과 데이터 평면 분리", "네트워크 기능을 범용 서버에서 실행하는 NFV만", "각 장비가 정책과 전달 판단을 독립 수행", "물리 링크를 논리적으로 묶는 링크 집성"],
["SDN은 제어 판단과 실제 전달 기능을 분리하여 네트워크를 프로그래밍 가능하게 관리하는 접근이다.", "NFV는 기능의 소프트웨어화에 초점을 둔다. 제어 평면·데이터 평면 분리라는 SDN 개념과 다르다.", "독립 장비의 제어·전달 결합은 사례의 중앙 정책 제어와 평면 분리 구조와 대비된다.", "링크 집성은 대역폭·중복성을 위해 연결을 묶으며 제어·전달 평면 분리 자체를 뜻하지 않는다."],['Control plane','Data plane']);
mc(8,2,s3('215','XVII 네트워크 가상화'),'NFV','전용 장비에서 소프트웨어로','방화벽·라우터 기능을 전용 하드웨어 대신 범용 서버의 가상 소프트웨어 인스턴스로 제공한다. 관련 개념은?',
["NFV", "SDN의 제어·데이터 평면 분리만", "VLAN 브로드캐스트 영역 분리", "포트 미러링"],
["NFV는 네트워크 기능을 소프트웨어로 가상화하여 범용 인프라에서 실행하는 접근이다.", "SDN은 제어 방식 분리에 초점을 두며 네트워크 기능을 범용 서버 소프트웨어로 실행하는 NFV와 구분한다.", "VLAN은 논리적 L2 영역 분리로 전용 장비 기능의 가상 소프트웨어화와 다르다.", "미러링은 분석용 트래픽 사본을 제공하는 기능이다."],['네트워크 기능의 소프트웨어화','SDN과 상호 보완 가능']);
mc(8,3,s3('134','IX 컨테이너'),'운영 자동화','죽은 프로세스의 재배치','클러스터 관리자가 실패한 컨테이너를 새 노드에 재배치했다. 이 사실만으로 보장할 수 없는 것은?',
['응용 데이터와 외부 의존성까지 완전히 복구됨','실행 인스턴스를 다시 배치할 수 있음','선언된 복제 수 회복을 시도할 수 있음','운영자의 반복 배치 업무를 줄일 수 있음'],['컨테이너 재배치와 상태 데이터·외부 서비스 복구는 다르다. 데이터 지속성 및 의존성 설계가 별도로 필요하다.','재배치는 오케스트레이션이 수행할 수 있는 기능이다.','원하는 상태를 선언하면 관리 시스템이 복제 수 회복을 시도할 수 있다.','자동 배치·감시는 반복적인 수작업을 줄일 수 있다.'],['실행 복구≠데이터 복구','상태 관리 설계']);
mc(8,4,s3('136','X 분산 처리'),'자원 관리','여러 작업의 자원 배정','Hadoop 클러스터에서 여러 작업이 메모리·CPU 자원을 경쟁한다. 자원 할당과 실행 조정에 관련된 구성요소는?',
["YARN", "HDFS", "Hive", "MapReduce 계산 함수만"],
["YARN은 Hadoop 클러스터의 자원 관리와 작업 실행을 조정하는 구성요소다.", "HDFS는 분산 파일을 저장하는 계층이다. CPU·메모리 자원 배정과 구분한다.", "Hive는 SQL 기반 분석 질의 계층으로 클러스터 자원 관리 체계 자체와 다르다.", "MapReduce는 계산을 구성하는 모델이다. 여러 작업에 자원을 배분하는 관리 체계는 YARN이다."],['저장·자원·질의 계층 분리','클러스터 자원 경쟁']);
mc(8,5,s3('76','V 병렬 처리'),'Flynn 분류','각 노드가 다른 프로그램 실행','각 계산 노드가 서로 다른 프로그램 명령을 실행하면서 서로 다른 데이터를 처리한다. 분류는?',
['MIMD','SIMD','SISD','MISD'],['복수 명령 스트림과 복수 데이터 스트림을 갖는 MIMD다.','SIMD는 하나의 명령 스트림이 여러 데이터에 적용되는 구조다.','SISD는 명령·데이터 스트림이 각각 하나다.','MISD는 복수 명령에 단일 데이터 스트림이라는 분류다.'],['명령 스트림 수','데이터 스트림 수']);
mc(8,6,s3('148','XI 데이터링크 계층'),'오류 검출','CRC가 알려주는 것','프레임의 CRC 검사에서 오류가 검출되었다. CRC의 역할에 대한 올바른 설명은?',
["우발적 비트 오류 검출에 사용하며 암호학적 발신자 인증을 대신하지 않는다.", "검사값이 있으므로 발신자 신원도 항상 인증된다.", "오류 검출에 성공하면 원문을 항상 자동 복원한다.", "CRC 값을 비밀키로 쓰면 전송 내용이 암호화된다."],
["CRC는 오류 검출용 검사값이다. 공격자가 검사값도 바꿀 수 있는 상황에서 메시지 인증 코드와 같지 않다.", "CRC는 일반적으로 비밀키를 쓰지 않으므로 공격자가 데이터를 바꾸고 검사값도 다시 계산할 수 있다.", "검출과 정정은 다르다. 오류가 있다는 판단만으로 모든 경우 원래 값을 알아낼 수 없다.", "CRC는 오류 검사용 요약값이지 기밀성을 제공하는 암호키·암호화 과정이 아니다."],['오류 검출≠인증','검출과 정정 구분']);
mc(8,7,s3('147–148','XI 오류 제어'),'오류 정정','재전송이 어려운 통신','심우주 통신처럼 재전송 비용이 커 수신 측이 추가 부호로 일부 오류를 바로 수정하게 한다. 해당 접근은?',
["전방 오류 정정(FEC)", "자동 반복 요청(ARQ)", "단순 CRC 검출만", "TCP 혼잡 윈도 조정"],
["FEC는 중복 부호를 더하여 허용 범위 내 오류를 수신 측에서 정정하게 한다.", "ARQ는 오류·누락을 발견하고 재전송을 요청하는 방식이다. 수신 측 자체 정정이라는 요구와 다르다.", "CRC만으로 오류를 검출할 수 있지만 정정 능력을 가진 부호가 없으면 원문을 자체 복구하지 못한다.", "혼잡 윈도는 네트워크 혼잡에 따라 송신량을 조절하며 오류 정정 부호와는 다르다."],['중복 비트와 정정 능력','재전송 비용 절충']);
mc(8,8,s3('169','XIII IP 주소'),'사설 주소','내부 주소 대역 선택','외부에 직접 라우팅할 공인 주소 대신 사내망용 IPv4 사설 주소를 골라야 한다. 해당하는 것은?',
['172.20.10.5','172.40.10.5','8.8.8.8','1.1.1.1'],['172.16.0.0/12는 172.16부터 172.31 범위의 사설 주소이며 172.20.10.5가 포함된다.','172로 시작한다고 모두 사설은 아니다. 172.40은 172.16/12 범위 밖이다.','8.8.8.8은 해당 사설 주소 범위에 포함되지 않는다.','1.1.1.1은 해당 사설 주소 범위에 포함되지 않는다.'],['10/8·172.16/12·192.168/16','범위 정확히 확인']);
mc(8,9,s4('51·53','III IoT 보안'),'IoT 생명주기','배포 후의 보안','센서 제조사가 출하 시 암호화를 적용했다. 이후 운영·폐기 단계에 대한 타당한 설명은?',
["업데이트·접근권한·저장정보 처리까지 생명주기 내내 관리해야 한다.", "출하 검사와 암호화 검증까지만 보안 범위로 지정", "업데이트 경로의 서명 검증은 편의상 제외", "폐기 시 기기 계정·저장정보 처리는 사용자에게만 맡김"],
["IoT 보안은 설계뿐 아니라 배포·운영·업데이트·폐기에 걸친 지속적인 관리가 필요하다.", "출하 이후에도 취약점과 운영 환경이 바뀔 수 있어 초기 검사만으로 전체 생명주기를 보호하지 못한다.", "업데이트의 출처·무결성 검증을 생략하면 악성 펌웨어 설치 위험이 생길 수 있다.", "사용자가 해야 할 절차도 필요하지만 제조·운영 정책에서 폐기와 잔여정보 처리를 고려해야 한다."],['보안 생명주기','운영·폐기의 잔여 정보']);
mc(8,10,s4('53','III 클라우드 보안'),'가상 네트워크','외부 방화벽에 안 보이는 흐름','같은 물리 호스트의 VM 사이 통신이 외부 물리 방화벽을 지나지 않는다. 적절한 보안 검토는?',
["가상 네트워크 내부의 가시성과 접근통제도 확인", "외부 경계 방화벽 로그만 분석하면 충분", "VM별 백신만 있으면 내부 통신 정책은 불필요", "가상 스위치에서 모든 VM을 같은 보안 영역으로 취급"],
["가상 네트워크 내부 경로는 외부 장비에 보이지 않을 수 있어 내부 통신의 감시·격리를 별도로 검토한다.", "물리 경계를 지나지 않는 통신이 있으므로 외부 로그만으로 내부 트래픽을 모두 관찰할 수 없다.", "백신과 통신 접근통제는 다른 계층의 방어이므로 단일 도구로 대체할 수 없다.", "서로 다른 신뢰 수준의 VM을 동일 영역으로 두면 침해의 수평 확산을 제한하기 어렵다."],['동서 트래픽','가상 환경의 가시성']);
mc(8,11,s4('117','VIII 무선랜 보안'),'무선 통제','강한 암호만 있으면 충분한가','무선 구간 암호화는 적용했지만 AP 분실·설정 무단 변경·담당자 부재가 우려된다. 타당한 설명은?',
["기술적 암호화와 함께 물리적·관리적 통제가 필요하다.", "무선 암호만 주기적으로 바꾸면 장비 관리 대체", "SSID를 숨기면 비인가 AP 점검 생략 가능", "AP 설정 백업만 있으면 도난 방지 통제 불필요"],
["암호화는 한 통제이며 장비 보호·설정 관리·책임자·점검 절차도 함께 필요하다.", "암호 교체는 유용하지만 자산·권한·장비 물리 보호와 담당자 관리까지 대신하지 않는다.", "SSID 숨김은 AP 신뢰성 검증과 자산 현황 관리를 대체하지 못한다.", "설정 복구와 장비 도난·정보 노출 예방은 서로 다른 목적의 통제다."],['관리·물리·기술 통제','다층 방어']);
mc(8,12,s4('80–81','VI DB 보안'),'접근통제','암호화된 DB의 정상 조회 오남용','DB 저장 파일은 암호화했지만 조회 권한이 과도한 직원이 민감 정보를 대량 조회했다. 추가로 필요한 통제는?',
["직무에 따른 조회 범위 제한과 접근 기록 점검", "저장 암호 알고리즘의 키 길이만 증가", "조회 결과의 전송 TLS만 강화", "직원 비밀번호만 바꾸고 조회 권한은 유지"],
["저장 암호화는 정상 조회 권한을 가진 사용자의 과도한 접근을 자동 제한하지 않는다. 권한과 감사를 보완한다.", "키 길이는 암호 해독 난이도에 영향을 주지만 정상 조회 권한으로 평문을 얻는 오남용을 제한하지 않는다.", "전송 보호를 강화해도 허가된 직원에게 민감 결과가 반환되는 접근 범위 문제는 남는다.", "현재 사용자가 가진 과도한 조회 권한은 비밀번호 변경만으로 줄어들지 않는다."],['저장 암호화와 접근통제','감사 가능성']);
mc(8,13,s4('59','IV 위험관리'),'잔여 위험','통제 이후에도 남는 가능성','접근통제와 모니터링을 적용했지만 모든 침해 가능성이 없어지지는 않았다. 남아 있는 위험을 무엇이라 하는가?',
["잔여 위험", "통제 적용 전의 고유 위험", "취약점 개수 자체", "위협 행위자의 공격 능력 자체"],
["잔여 위험은 통제를 적용한 뒤에도 남아 있는 위험이다. 수준을 평가하고 추가 처리 또는 승인을 결정한다.", "고유 위험은 통제 적용 전 위험을 말하며 통제 이후 남은 잔여 위험과 구분한다.", "취약점 수만으로 자산 영향·기존 통제까지 반영한 위험 수준을 나타낼 수 없다.", "공격 능력은 위협 평가 요소이며 통제를 적용한 뒤 조직에 남은 위험 전체와 다르다."],['통제 전후 위험','수용 가능한 수준']);
mc(8,14,s4('69','V 시큐어 SDLC'),'변경 보안','업데이트 기능의 영향','인증 흐름을 수정한 새 버전을 배포하려 한다. 유지보수 단계에서 적절한 활동은?',
["변경의 보안 영향을 평가하고 관련 회귀 검증을 수행", "변경 파일에 대한 문법 검사만 수행", "기존 보안 시험 통과 결과를 그대로 재사용", "배포 승인 후 보안 영향 분석은 생략"],
["변경은 새 취약점이나 기존 통제의 우회를 만들 수 있어 영향 분석과 검증이 필요하다.", "문법 검사는 실행 가능성을 점검하지만 인증 우회·권한 누락 같은 논리적 보안 결함을 모두 잡지 못한다.", "변경된 흐름에는 이전 시험이 적용되지 않을 수 있어 영향 범위에 따른 회귀 검증이 필요하다.", "배포 승인은 영향을 검토한 근거가 있어야 하며 승인 자체가 보안 분석을 대신하지 않는다."],['변경 영향 분석','보안 회귀 검증']);
mc(8,15,s4('89','VI 키 관리'),'마스터 키','데이터 키를 다시 암호화','데이터를 암호화하는 키를 별도의 상위 키로 보호해 저장한다. 상위 키의 역할은?',
["암호화 키 자체의 보호", "데이터의 압축", "전자서명 검증키의 공개 배포", "네트워크 세션의 순서번호 부여"],
["마스터 키 또는 키 암호화 키는 데이터 암호화 키를 보호하는 데 사용되며 접근을 더 엄격히 제한한다.", "암호키를 다른 키로 보호하는 목적은 비밀 보호이며 압축률 향상이 아니다.", "서명 검증 공개키 배포는 키의 신뢰 전파와 관련된다. 데이터 암호키를 상위 비밀키로 감싸는 것과 다르다.", "순서번호는 통신의 순서·중복 판단용이며 저장 암호키의 보호 역할이 아니다."],['키 계층화','마스터 키 접근 제한']);

// 9회차: 측정값과 운영 증거를 해석하는 응용.
mc(9,1,s3('54','III CPU 스케줄링'),'선점 스케줄링','더 짧은 작업의 도착','현재 작업의 남은 실행 시간은 9ms다. 2ms짜리 새 작업이 도착하자 즉시 현재 작업을 중단하고 새 작업을 실행했다. 가장 가까운 정책은?',
['최단 잔여 시간 우선(SRT)','비선점 FCFS','비선점 SJF','페이지 FIFO'],['SRT는 현재 작업의 남은 시간과 대기 작업 시간을 비교하는 선점형 최단 작업 정책이다.','FCFS는 도착 순 처리이므로 새 짧은 작업만으로 즉시 선점하지 않는다.','비선점 SJF는 다음 작업 선택 때 짧은 작업을 고르지만 실행 중 작업을 이런 방식으로 선점하지 않는다.','페이지 FIFO는 메모리 교체 정책으로 CPU 실행 선점 기준이 아니다.'],['SRT는 선점형','SJF와 구분']);
mc(9,2,s3('54','III CPU 스케줄링'),'HRN','오래 기다린 작업의 비율','HRN의 응답비율을 (대기시간+서비스시간)/서비스시간으로 계산한다. 대기 12, 서비스 4인 작업의 비율은?',
['4','3','16','0.25'],['(12+4)/4=4다. 대기 시간이 서비스 시간에 비해 길수록 비율이 커진다.','12/4만 계산하여 분자의 서비스시간을 빠뜨린 값이다.','16은 분자 합이며 서비스시간으로 나누지 않았다.','0.25는 정답의 역수이며 주어진 공식과 다르다.'],['HRN 공식','대기시간 반영']);
mc(9,3,s3('55','III 가상 메모리'),'페이지 교체','미래를 아는 기준','앞으로 가장 오랫동안 사용하지 않을 페이지를 교체하는 이론적 기준을 성능 비교에 사용한다. 해당 알고리즘은?',
['OPT','LRU','FIFO','LFU'],['OPT는 미래 참조를 알고 가장 늦게 다시 쓰일 페이지를 내보내는 최적 기준이다. 실제 온라인 구현에는 미래 정보 제약이 있다.','LRU는 과거 최근 참조 시점을 사용하는 알고리즘이다.','FIFO는 적재된 순서가 가장 오래된 페이지를 고른다.','LFU는 과거 참조 횟수를 비교한다.'],['미래 정보 필요','이론적 비교 기준']);
mc(9,4,s3('49','III 동기화'),'임계구역','한 명만 들어가게 하기','공유 큐의 상태 변경 구간에 한 번에 하나의 스레드만 들어가도록 한다. 직접 만족시키려는 조건은?',
["상호 배제", "진행 조건", "한정 대기", "선점형 스케줄링"],
["상호 배제는 공유 자원의 임계구역을 동시에 여러 실행이 변경하지 않도록 하는 조건이다.", "진행 조건은 임계구역이 비어 있을 때 진입 결정이 무기한 미뤄지지 않도록 하는 조건으로 동시 진입 금지와 다르다.", "한정 대기는 진입하려는 스레드가 무한히 기다리지 않도록 하는 공정성 관련 조건이다.", "선점은 CPU 실행을 중단하고 다른 작업에 배정하는 정책이다. 공유 갱신 구간의 동시 진입을 직접 금지하지 않는다."],['Mutual Exclusion','공유 상태 보호']);
mc(9,5,s3('170','XIII IP 주소'),'서브넷 범위','호스트의 네트워크 주소','IPv4 주소 192.168.8.70/26의 네트워크 주소는?',
['192.168.8.64','192.168.8.0','192.168.8.70','192.168.8.127'],['/26은 마지막 옥텟을 64개 단위로 나눈다. 70은 64~127 구간에 있어 네트워크 주소는 .64다.','.0은 0~63 구간의 네트워크 주소다.','.70은 주어진 호스트 주소이며 호스트 비트가 모두 0이 아니다.','.127은 해당 /26 구간의 브로드캐스트 주소다.'],['블록 크기 64','네트워크·호스트·브로드캐스트']);
mc(9,6,s3('172','XIII IP 주소'),'IPv6','주소 공간의 변화','IPv4 32비트 주소 공간과 비교하여 IPv6 주소의 비트 수로 적절한 것은?',
['128비트','64비트','48비트','256비트'],['IPv6 주소는 128비트이며 IPv4보다 훨씬 큰 주소 공간을 제공한다.','64비트는 IPv6 주소 전체 길이가 아니다.','48비트는 흔한 MAC 주소 길이로 IPv6 전체 주소와 다르다.','IPv6 주소 길이는 256비트가 아니다.'],['IPv4 32비트','IPv6 128비트']);
mc(9,7,s3('166','XII 라우팅'),'링크 상태','영역 내 토폴로지 계산','라우터들이 링크 상태 정보를 교환하여 네트워크 토폴로지와 최단 경로를 계산한다. 대표적인 IGP는?',
['OSPF','RIP','BGP','SMTP'],['OSPF는 링크 상태 기반 내부 라우팅 프로토콜이다.','RIP는 거리 벡터 기반이며 링크 상태 알고리즘과 구분한다.','BGP는 AS 간 경로·정책 교환에 사용되는 경로 벡터 계열이다.','SMTP는 메일 전송용 응용 프로토콜이다.'],['OSPF=링크 상태','RIP=거리 벡터']);
mc(9,8,s3('158','XII 스위칭'),'트래픽 관찰','분석 장비로 프레임 사본 전달','업무 트래픽의 사본을 별도 분석 장비에 보내려 한다. 스위치에서 관련된 기능은?',
["포트 미러링", "STP", "VLAN", "포트 기반 인증"],
["포트 미러링은 선택한 포트·트래픽의 사본을 모니터링 포트로 전달한다. 수집 범위와 민감정보 보호를 고려한다.", "STP는 브리지 루프를 억제하는 프로토콜로 트래픽 사본을 분석 포트로 보내는 기능이 아니다.", "VLAN은 논리적 네트워크 영역을 구분하며 감시용 사본 전송과 다르다.", "포트 기반 인증은 연결 주체의 네트워크 접근을 허용할지 판단하는 통제로 미러링과 구분한다."],['미러링=관찰용 사본','모니터링 범위']);
mc(9,9,s4('64','IV 취약점 평가'),'CVSS','심각도 숫자 해석','취약점의 기술적 심각도 점수를 읽었다. 조직의 실제 조치 순위를 정할 때 적절한 설명은?',
['점수와 함께 자산 중요도·노출·악용 가능 조건을 검토한다.','같은 점수는 언제나 같은 업무 위험을 뜻한다.','점수가 있으면 패치 시험은 불필요하다.','점수는 취약점 종류의 고유 ID다.'],['기술적 심각도는 판단 자료이며 실제 조직 위험은 환경과 업무 영향도 함께 고려해야 한다.','같은 기술적 점수라도 환경·통제·업무 영향이 다를 수 있다.','패치는 서비스 호환성과 안전한 적용을 위한 검증이 필요하다.','고유 ID와 심각도 점수는 다르며 여러 취약점이 같은 점수를 가질 수 있다.'],['심각도와 업무 위험 구분','환경 맥락']);
mc(9,10,s4('35–37','II 전자서명'),'서명과 암호화','서명만 한 문서의 열람','문서를 전자서명했지만 원문은 평문으로 공개했다. 이때 서명만으로 제공되지 않는 속성은?',
['문서 내용의 기밀성','내용 변경 검증','서명키 소유자와의 연계 검증','서명자의 공개키를 이용한 검증'],['전자서명은 무결성과 출처 확인에 쓰인다. 공개된 평문 내용을 숨기는 기밀성은 별도 암호화가 필요하다.','서명된 내용이 바뀌면 검증 실패로 변경을 알아낼 수 있다.','신뢰할 수 있는 공개키와 검증 절차를 통해 대응 개인키로 생성한 서명임을 확인한다.','공개키 검증은 전자서명의 기본 구조다.'],['서명≠암호화','평문 공개와 기밀성']);
mc(9,11,s4('37','II PKI'),'인증서 생명주기','개인키가 유출된 경우','인증서 유효기간은 남았지만 대응 개인키가 유출되었다. 적절한 대응 방향은?',
['인증서 폐지 등 신뢰 철회와 새 키 발급 절차 수행','유효기간이 끝날 때까지 무조건 유지','공개키만 비밀 폴더로 이동','키 파일 이름만 변경'],['개인키 유출은 서명·인증 위조 위험을 만든다. 유효기간과 별개로 폐지와 키 교체가 필요하다.','만료 전이라도 키가 유출되면 기존 신뢰를 유지할 수 없다.','공개키를 숨기는 것은 유출된 개인키의 악용을 막지 못한다.','파일명 변경은 키 값이나 신뢰 상태를 바꾸지 않는다.'],['만료와 폐지 구분','키 침해 대응']);
mc(9,12,s4('40–41','II 접근통제'),'권한 검토','인사 이동 후 남은 권한','영업 직원이 인사팀으로 이동했지만 이전 고객 대량 다운로드 권한도 유지됐다. 방지책으로 적절한 것은?',
["역할 변경 시 기존 권한 회수와 새 권한 재검토", "새 역할의 권한만 추가하고 이전 역할은 유지", "계정 이름을 새 부서명으로 수정", "새 부서에서만 다중요소 인증을 추가"],
["권한은 현재 직무에 맞게 회수·재부여해야 한다. 누적된 과잉 권한은 최소 권한 원칙을 위반한다.", "권한 추가만 반복하면 이전 직무의 불필요한 권한이 누적된다.", "계정의 표시 이름과 실제 허용된 권한은 별개다.", "다중요소 인증은 계정 탈취 대응에 도움 되지만 사용자가 가진 과도한 데이터 권한을 회수하지 않는다."],['권한 누적 방지','Joiner·Mover·Leaver 관리']);
mc(9,13,s4('69–70','V 시큐어 코딩'),'바인딩 한계','정렬 열 이름의 처리','SQL 값은 바인딩한다. 사용자가 요청한 정렬 열 이름은 쿼리 구조에 들어가야 한다. 안전한 설계는?',
['허용된 열 이름을 서버의 고정 SQL 조각에 매핑','입력 문자열을 그대로 ORDER BY 뒤에 결합','값 바인딩이 다른 모든 문자열 결합도 자동 보호','관리자 권한으로 쿼리를 실행'],['바인딩은 값과 구조를 분리한다. 열 이름처럼 구조에 들어가는 입력은 정해진 허용 목록에서 선택하도록 한다.','검증 없는 구조 문자열 결합은 SQL 삽입 위험을 남긴다.','한 매개변수 바인딩이 다른 곳의 문자열 결합 취약점까지 보호하지 않는다.','권한 증가는 구조 검증 결함을 해결하지 않고 피해를 키울 수 있다.'],['값과 식별자 구분','허용 목록 매핑']);
mc(9,14,s4('97','VII 시스템 보안'),'파일 권한','공용 설정 파일의 쓰기 권한','모든 사용자가 읽는 로그인 환경 설정 파일을 일반 사용자도 수정할 수 있다. 우선 줄여야 할 권한은?',
['불필요한 일반 사용자의 쓰기 권한','필요한 사용자의 읽기 권한만','파일 이름을 볼 권한만','관리자 감사 권한'],['공용 실행 환경 설정을 일반 사용자가 수정하면 다른 사용자 환경에 영향을 줄 수 있어 쓰기 권한을 제한한다.','읽기 제한만으로 현재의 무단 수정 문제를 해결하지 못한다.','파일명을 숨겨도 쓰기 권한이 남으면 변경 가능성이 유지된다.','감사 권한을 줄이는 것은 무단 수정 탐지·확인에 도움이 되지 않는다.'],['읽기와 쓰기 구분','공유 설정 무결성']);
mc(9,15,s4('46·59','III APT·IV 위험관리'),'다층 방어','백신 탐지 우회의 대비','백신이 놓친 침입 가능성에 대비하여 중요정보 접근을 제한하고 내부 행위를 관찰한다. 이 설계의 타당한 이유는?',
["하나의 통제가 실패해도 다른 통제로 피해를 제한하기 위해서", "내부망은 신뢰 영역이므로 권한 검사는 생략해도 됨", "로그를 많이 수집하면 자동으로 모든 침입이 차단됨", "암호화가 있으면 접근권한은 넓게 허용해도 됨"],
["예방·탐지·영향 제한을 함께 적용하면 단일 통제의 실패가 전체 보호 실패로 이어지는 위험을 줄일 수 있다.", "내부망도 침입·내부자 위협이 있을 수 있어 네트워크 위치만으로 자원 접근을 신뢰해서는 안 된다.", "로그 수집은 분석·탐지의 기반이며 실제 차단·조사·대응 설계가 별도로 필요하다.", "암호화는 정상 접근권한을 가진 사용자의 오남용을 모두 막지 못하므로 권한 통제도 필요하다."],['단일 통제의 한계','예방·탐지·대응']);

// 10회차: 분야 간 경계를 구분하는 종합 점검.
mc(10,1,s3('46','III 운영체제'),'프로세스 상태','입출력 완료 뒤의 위치','입출력 대기 중인 프로세스의 작업이 끝났다. CPU는 다른 프로세스가 쓰고 있다. 보통 이동하는 상태는?',
['준비','즉시 종료','영구 대기','항상 실행'],['입출력 완료로 실행 가능해지면 준비 큐에 들어가 CPU 배정을 기다린다.','입출력 완료가 프로세스 전체 작업 종료를 뜻하지 않는다.','기다리던 사건이 끝났으므로 해당 입출력 때문에 계속 대기할 이유는 없다.','CPU 배정은 스케줄러가 결정하므로 완료 즉시 항상 실행되는 것은 아니다.'],['대기→준비','사건 완료와 CPU 배정 분리']);
mc(10,2,s3('50','III 교착 상태'),'교착과 느린 작업','서로의 잠금을 기다리기','스레드 X는 잠금 A를 보유하고 B를 기다린다. Y는 B를 보유하고 A를 기다리며 누구도 잠금을 해제하지 못한다. 가장 적절한 진단은?',
["교착 상태", "기아 상태만", "라이브락", "긴 CPU 연산"],
["서로 자원을 보유한 채 상대 자원을 기다리는 순환 대기가 형성되어 진행이 멈춘 교착 상태다.", "기아는 특정 작업이 계속 실행 기회를 얻지 못하는 상황이다. 사례는 두 잠금의 순환 대기가 직접 원인이다.", "라이브락은 상태를 계속 바꾸지만 유효한 진행을 못하는 상황이다. 여기서는 잠금을 기다리며 정지했다.", "긴 연산은 시간이 걸려도 실행이 진행된다. 사례는 서로 자원 해제를 기다려 진행할 수 없다."],['자원 보유와 대기','순환 대기']);
mc(10,3,s3('54','III 스케줄링'),'시간 할당량','시간 조각을 지나치게 줄이기','라운드 로빈의 시간 조각을 아주 작게 줄였다. 고려해야 할 비용은?',
["문맥 교환 빈도와 오버헤드 증가", "평균 응답 시간은 줄어도 교환 비용은 고려할 필요 없음", "할당량을 줄이면 입출력 대기도 같은 비율로 감소", "시간 조각이 짧을수록 모든 작업의 완료 시간이 반드시 감소"],
["시간 조각이 짧으면 교체가 잦아져 응답성 이점과 문맥 교환 비용을 함께 고려해야 한다.", "응답성 이점이 있어도 잦은 문맥 교환은 실제 계산에 쓸 시간을 줄일 수 있다.", "CPU 시간 조각은 장치의 물리적 입출력 완료 시간을 직접 단축하지 않는다.", "교환 비용과 작업 특성 때문에 완료 시간이 항상 줄어드는 것은 아니다."],['응답성과 오버헤드 절충','RR 시간 조각']);
mc(10,4,s3('55','III 메모리 관리'),'주소 공간','고정 단위와 가변 단위','메모리를 고정 크기 블록으로 나누는 방식과 프로그램의 논리적 가변 크기 단위로 나누는 방식을 순서대로 고르면?',
['페이징·세그멘테이션','세그멘테이션·페이징','FIFO·LRU','SMP·MPP'],['페이징은 고정 크기 페이지·프레임, 세그멘테이션은 논리적 가변 크기 구역을 이용한다.','두 방식의 단위 특성을 반대로 연결했다.','FIFO와 LRU는 교체 대상을 고르는 알고리즘이며 주소 공간 분할 방식이 아니다.','SMP와 MPP는 병렬 컴퓨터 구조다.'],['페이징=고정 크기','세그멘트=논리적 가변 크기']);
mc(10,5,s3('81','V 파이프라인'),'제어 해저드','분기 결과가 아직 모른다','조건 분기의 결과가 늦게 확정되어 다음에 실행할 명령 경로가 불분명하다. 해당 위험은?',
["제어 해저드", "데이터 해저드", "구조적 해저드", "캐시 미스만"],
["분기·점프 등에 따라 명령 흐름이 달라지는 제어 해저드다.", "데이터 해저드는 앞 명령의 결과 의존성 때문에 피연산자가 준비되지 않은 경우다.", "구조적 해저드는 여러 명령이 같은 하드웨어 자원을 요구하는 충돌이다.", "캐시 미스는 필요한 명령·데이터가 캐시에 없어 발생하는 지연이다. 주어진 직접 원인은 분기 경로 불확실성이다."],['분기와 명령 흐름','해저드 원인 구분']);
mc(10,6,s3('120–121','VIII 가용성'),'서비스 연속성','가용성과 백업의 차이','파일이 실수로 삭제됐고 삭제 상태가 실시간 복제본에도 전파됐다. 이를 되돌릴 능력을 평가할 때 중요한 것은?',
["과거 시점 복구 사본과 복원 시험", "현재 상태 복제본 수만 늘림", "동기 복제의 확인 응답을 더 빠르게 함", "삭제 권한이 있는 동일 계정으로 사본도 모두 관리"],
["현재 상태 복제는 삭제도 전파할 수 있다. 과거 시점 사본과 복원 절차가 있어야 논리 오류 복구를 평가할 수 있다.", "삭제를 같은 방식으로 전파하는 사본만 늘려도 삭제 이전 시점으로 복원할 수 있다는 보장은 없다.", "동기 복제 속도를 높이는 것만으로 잘못된 삭제 이전의 기록을 유지하지는 못한다.", "한 계정이 모든 사본을 변경·삭제할 수 있으면 잘못된 작업이나 계정 침해의 영향 범위가 넓어진다."],['복제≠백업','논리 오류의 복구 시점']);
mc(10,7,s3('127–128','IX 클라우드'),'책임 분담','서비스 모델이 바뀌면','직접 운영하던 메일 서버를 완성된 웹메일 서비스로 전환했다. 가장 타당한 설명은?',
['응용 운영 부담은 줄지만 계정·데이터 사용 권한 등의 책임은 확인해야 한다.','SaaS이면 이용자 측 보안 책임이 완전히 없다.','물리 디스크를 이용자가 직접 교체해야 SaaS다.','서비스 모델과 책임 범위는 항상 무관하다.'],['SaaS는 공급자가 많은 운영을 담당하지만 이용자의 계정·접근권한·데이터 관리 책임은 계약과 기능에 따라 남는다.','서비스 이용만으로 모든 보안 책임이 없어지지는 않는다.','물리 디스크 직접 운영은 SaaS 이용의 필수 조건이 아니다.','IaaS·PaaS·SaaS는 관리 계층에 차이가 있으므로 책임 분담을 확인해야 한다.'],['완성 응용의 이용','공급자·이용자 책임']);
mc(10,8,s3('178·185','XIV 전송 계층'),'TCP와 UDP','중복 요청을 막는 설계','TCP로 결제 요청을 보냈지만 응답 전에 연결이 끊겨 재요청했다. TCP의 신뢰성만으로 확정할 수 없는 것은?',
['업무 결제가 정확히 한 번 처리됐는지','한 연결에서 바이트 순서를 관리한다는 것','전송 손실을 재전송으로 보완한다는 것','UDP와 다른 신뢰성 기능을 제공한다는 것'],['TCP 바이트 전달과 업무 트랜잭션의 완료·중복 처리는 다르다. 요청 식별자와 멱등성·결과 조회 같은 응용 설계가 필요하다.','TCP는 연결 내 바이트 순서 관리 기능을 제공한다.','TCP의 신뢰성 기능에는 손실 감지와 재전송이 포함된다.','UDP 자체와 비교하면 TCP는 연결·재전송·순서 관리 기능이 있다.'],['전송 신뢰성과 업무 완료 구분','중복 요청 처리']);
mc(10,9,s4('13','I 정보보안 개요'),'보안 속성','세 사건의 대응 목표','고객 명단 유출, 결제 금액 무단 변경, 예약 사이트 접속 불가의 직접 침해 속성을 순서대로 고르면?',
['기밀성·무결성·가용성','가용성·기밀성·무결성','무결성·가용성·기밀성','모두 기밀성만'],['정보 유출은 기밀성, 무단 변경은 무결성, 서비스 이용 불가는 가용성의 직접 침해다.','첫 사건은 이용 불가가 아닌 노출이고 둘째는 노출보다 변경이 핵심이다.','각 속성을 순환해 잘못 연결했다. 변경·노출·중단을 구분한다.','일부 사건이 함께 여러 속성을 침해할 수 있지만 제시한 직접 현상은 서로 다르다.'],['CIA 사례 매핑','직접 피해와 부수 영향']);
mc(10,10,s4('110','VIII IPsec'),'보안 프로토콜','패킷 인증과 암호화 구성','IPsec에서 패킷 보호 구성요소를 비교한다. 인증·무결성을 다루지만 페이로드 기밀성 암호화 자체를 제공하지 않는 것은?',
['AH','ESP의 암호화 기능','AES 암호화','암호화된 VPN 터널 전체'],['AH는 인증·무결성 보호를 제공하지만 페이로드 암호화 기능은 제공하지 않는다. ESP는 구성에 따라 암호화 등을 제공한다.','ESP는 암호화 서비스 제공에 사용되는 IPsec 구성요소다.','AES는 기밀성 보호에 사용하는 대칭키 암호 알고리즘이다.','암호화된 터널 전체를 기밀성 제공이 없는 구성요소라고 부를 수 없다.'],['AH와 ESP 역할','인증과 기밀성 구분']);
mc(10,11,s4('27','II 암호 기술'),'해시 한계','기대 해시까지 바뀌었다','공격자가 배포 파일과 같은 서버에 있는 기대 해시 문자열을 모두 바꿀 수 있다. 해시 일치 검사만의 한계는?',
['변조된 파일과 새 해시가 함께 일치해도 신뢰할 수 없다.','해시가 일치하면 출처는 무조건 보증된다.','해시는 파일을 암호화하므로 공격자가 볼 수 없다.','파일 길이만 같으면 해시 검사는 필요 없다.'],['비교 기준도 공격자가 바꿀 수 있으면 단순 해시 일치는 정당한 출처를 증명하지 못한다. 신뢰된 서명·별도 경로 등이 필요하다.','일반 해시는 비밀키나 서명자 신원 인증을 제공하지 않는다.','해시는 요약값이며 파일 내용을 숨기는 암호화가 아니다.','길이가 같아도 내용이 다를 수 있으므로 길이는 무결성 검증을 대체하지 않는다.'],['신뢰된 기준값','해시와 전자서명']);
mc(10,12,s4('89','VI 암호키 관리'),'키 생성','예측 가능한 키','개발자가 현재 시각을 그대로 비밀키로 사용하려 한다. 올바른 개선 방향은?',
["검증된 암호학적 난수 생성과 적절한 키 생성 절차 사용", "현재 시각의 해시만 사용", "연속된 사용자 번호를 키로 사용", "난수 생성은 생략하고 키 길이만 늘림"],
["공격자가 예측하기 어려운 키가 필요하므로 안전한 난수와 검증된 생성 절차를 사용한다.", "공개되거나 추측 가능한 시각을 해시해도 가능한 입력을 계산해 키를 추측할 수 있다.", "연속 번호는 예측 가능하므로 비밀키의 필요한 불확실성을 제공하지 못한다.", "길이가 길더라도 생성 과정이 예측 가능하면 키 후보를 좁힐 수 있어 안전한 생성이 필요하다."],['키의 예측 불가능성','키 비밀 보호']);
mc(10,13,s4('41·81','II·VI 접근통제'),'DAC','자료 소유자의 권한 부여','문서 소유자가 팀원을 골라 읽기 권한을 부여하고 회수한다. 이 설명에 가까운 접근통제는?',
['DAC','MAC','강제 등급 흐름만','동기식 복제'],['DAC는 객체 소유자의 재량에 따라 다른 주체의 접근을 허용·회수하는 모델이다.','MAC는 소유자 재량보다 중앙의 강제 보안 정책이 중심이다.','등급에 따른 강제 통제는 이 사례의 소유자 재량 부여와 구분한다.','복제는 데이터 사본 관리 방식이며 접근통제 모델이 아니다.'],['객체 소유자의 재량','부여·회수 권한']);
mc(10,14,s4('71','V 시큐어 코딩'),'명령 삽입','사용자 입력으로 셸 문자열 생성','운영 도구가 사용자가 입력한 이름을 셸 명령 문자열에 그대로 결합한다. 안전한 설계 방향은?',
["가능하면 전용 API로 대체하고 입력을 허용 범위로 제한", "셸 구분 문자 한 종류만 제거", "셸 인자를 분리하면 모든 입력 의미 검증도 생략", "실행 계정 권한만 낮추고 위험한 문자열 결합은 유지"],
["셸 해석을 피하는 전용 API와 명확한 입력 허용 규칙으로 명령 구조에 입력이 영향을 주는 경로를 줄인다.", "한 문자 제거는 다른 해석 규칙이나 우회 형태를 모두 처리하지 못할 수 있다.", "인자 분리는 셸 해석 위험을 줄이지만 대상 프로그램의 옵션·경로 해석에 맞는 허용값 검증도 필요하다.", "최소 권한은 피해를 줄이지만 잘못된 명령 실행 결함 자체를 해결하지 않는다."],['명령과 데이터 분리','셸 사용 최소화']);
mc(10,15,s4('58–59','IV 보안관리체계'),'관리체계 개선','훈련 뒤 발견한 빈틈','복구 훈련에서 담당자 연락망과 승인 절차 누락을 발견했다. 관리체계에 맞는 후속 활동은?',
["원인을 분석하고 절차·책임·교육을 수정한 뒤 다시 검증", "점검 증거만 보관하고 후속 조치 담당자는 지정하지 않음", "기술 장비 시험만 다시 하고 연락·승인 절차는 제외", "목표 수치를 실제 실패 결과에 맞춰 근거 없이 완화"],
["관리체계는 점검 결과를 개선으로 연결해야 한다. 수정된 책임과 절차의 효과도 후속 검증한다.", "기록은 필요하지만 개선 책임과 기한을 정하지 않으면 발견된 절차 문제가 그대로 남을 수 있다.", "복구에는 장비뿐 아니라 사람과 의사결정 절차가 필요하므로 기술 시험만으로 부족하다.", "목표는 업무 영향과 위험 평가에 근거해야 하며 실패를 감추기 위한 임의 완화는 개선이 아니다."],['점검 결과의 개선 연결','사람·절차·기술']);


export const systemsQuestions: Question[] = [...bank, ...systemsOpenQuestions].sort((a, b) => a.round - b.round || Number(a.id.split("-").at(-1)) - Number(b.id.split("-").at(-1)));
